const r={acpa:[{n:"服部",mf:"荒坂",type:"轻",intro:"刺杀潜入，忍者专用",ra:"SSR",lore:"",parts:{头部组件:[{n:"低感知目镜",mf:"甘四郎",type:"轻",ar:"7",hp:"17",slot:"4",ds:"全HUD宽幅式，低感态",pr:5900,ra:"R"},{n:"强攻-3多面感知头盔",mf:"世嘉达利",type:"中",ar:"19",hp:"30",slot:"6",ds:"环境计算集成式宽幅HUD",pr:1e4,ra:"SR"},{n:"服部原装高功能潜入系统",mf:"世嘉达利",type:"轻",ar:"15",hp:"20",slot:"7",ds:"反应+1，虚拟实景交互界面",pr:20500,ra:"SSR"}],身体组件:[{n:"服部原装线性框架",mf:"荒坂",type:"轻",ar:"18",hp:"45",slot:"6",ds:"反应+1，敏捷+1 体格12，可以闪避子弹",pr:35e3,ra:"SR"},{n:"强攻-G强化框架",mf:"三菱",type:"中",ar:"25",hp:"60",slot:"7",ds:"反应+1，敏捷+2，体格14，整合了复合合金装甲",pr:43e3,ra:"SR"},{n:"神隐零号 实验框架",mf:"荒坂",type:"轻",ar:"19",hp:"50",slot:"8",ds:"敏捷+2，体格11，可以闪避子弹，整合了特种隐身装置",pr:5e4,ra:"SSR"}],手部组件:[{n:"忍者A轻装外骨骼",mf:"荒坂",type:"轻",ar:"15",hp:"25",slot:"1",ds:"低增强，武术+1",pr:13e3,ra:"R"},{n:"服部原装仿生肌肉束",mf:"荒坂",type:"轻",ar:"15",hp:"27",slot:"2",ds:"高增强，武术+2",pr:21e3,ra:"SR"},{n:"半藏-K 特装忍手甲",mf:"菅生",type:"轻",ar:"17",hp:"30",slot:"2",ds:"高增强，武术+2，自带一个手里剑弹射器",pr:24e3,ra:"SSR"},{n:"“蜘蛛骨”强攻手甲",mf:"菅生",type:"中",ar:"18",hp:"40",slot:"4",ds:"超控增强，额外附带一只同样灵敏的机械手臂，损失20hp后，额外的机械臂损坏",pr:44e3,ra:"SSR"}],腿部组件:[{n:"“猫足”无声靴",mf:"荒坂",type:"轻",ar:"15",hp:"20",slot:"2",ds:"无声移动，敏捷+1",pr:14e3,ra:"SR"},{n:"“虎爪”攀爬爪",mf:"菅生",type:"轻",ar:"17",hp:"22",slot:"1",ds:"敏捷+1，整合了攀爬爪",pr:13e3,ra:"SR"},{n:"强攻-G 足部装甲",mf:"荒坂",type:"中",ar:"22",hp:"30",slot:"2",ds:"移动+2，敏捷+1，整合了全向动力轮",pr:26e3,ra:"SR"}]},notes:{头部组件:"服部系列是荒坂为了潜入作战而特化的轻型ACPA，由于多种技术的实验性质，这种ACPA的高级改装型号只有荒坂内部的忍者部队装备。这些精锐忍者通常不会携带过于强大的火力，只专注于袭扰敌方后方，或者守护荒坂的重要设施。在荒坂之外，服部也有少量出口，一般都是日本的荒坂盟友。据说东京警视厅里有三架特别改装的服部ACPA用来防范赛博精神病或者可能的外部恐怖袭击。"},grp:""},{n:"突击-4",mf:"军科",type:"中",intro:"战场中坚，量产型突击装甲",ra:"R",lore:"",parts:{头部组件:[{n:"龙龟型重型装甲头盔",mf:"梅塔",type:"重",ar:"26",hp:"40",slot:"4",ds:"增强式观察窗",pr:9e3,ra:"R"},{n:"ASG-7战场监控系统",mf:"渡微",type:"轻",ar:"15",hp:"20",slot:"6",ds:"虚拟实景交互界面",pr:25e3,ra:"SSR"},{n:"突击α装甲骑兵舱",mf:"梅塔",type:"重",ar:"22",hp:"35",slot:"4",ds:"宽幅式观察窗",pr:14e3,ra:"SR"},{n:"突击β智控头盔",mf:"军科",type:"中",ar:"20",hp:"30",slot:"7",ds:"环境计算集成式宽幅HUD",pr:2e4,ra:"SR"}],身体组件:[{n:"军团 复合巷战框架",mf:"梅塔",type:"重",ar:"29",hp:"75",slot:"5",ds:"移动-1，敏捷-1，体格16，整合了逃生装置",pr:3e4,ra:"SR"},{n:"突击-4原装装甲",mf:"军科",type:"中",ar:"25",hp:"45",slot:"6",ds:"体格14，整合了战场急救装置",pr:29e3,ra:"R"},{n:"海格力斯工程外骨骼",mf:"新科",type:"中",ar:"23",hp:"50",slot:"4",ds:"移动-1，敏捷-2，体格18",pr:15e3,ra:"N"},{n:"游骑兵框架",mf:"军科",type:"轻",ar:"18",hp:"40",slot:"7",ds:"敏捷+2，体格12",pr:28e3,ra:"SSR"}],手部组件:[{n:"海格力斯重装机械手",mf:"新科",type:"重",ar:"19",hp:"30",slot:"0",ds:"基本控制",pr:1500,ra:"N"},{n:"突击-4原装外骨骼",mf:"军科",type:"中",ar:"19",hp:"25",slot:"1",ds:"高级控制",pr:8e3,ra:"R"},{n:"游骑兵型仿生肌肉束",mf:"军科",type:"轻",ar:"17",hp:"20",slot:"2",ds:"低增强",pr:11e3,ra:"SSR"},{n:"军团型 重装机械臂",mf:"梅塔",type:"重",ar:"21",hp:"40",slot:"2",ds:"高级控制 自带高级武器挂架",pr:14e3,ra:"SR"}],腿部组件:[{n:"海格力斯承重型外骨骼",mf:"新科",type:"重",ar:"19",hp:"40",slot:"2",ds:"移动-1，体格+1",pr:5e3,ra:"N"},{n:"突击-4原装装甲足",mf:"军科",type:"中",ar:"17",hp:"32",slot:"3",ds:"敏捷+1",pr:18e3,ra:"R"},{n:"游骑兵-2高速突击足",mf:"军科",type:"轻",ar:"15",hp:"25",slot:"2",ds:"移动+2，整合了动力滑行器",pr:29e3,ra:"SSR"},{n:"军团 装甲履带",mf:"梅塔",type:"重",ar:"21",hp:"50",slot:"2",ds:"整合了履带足，奔跑时移动+2",pr:23e3,ra:"SR"}]},notes:{头部组件:"军用科技的主力ACPA，也是第三世界的战场上最常见的ACPA。无论是巷战攻坚，还是野战对抗装甲部队，它们都是性价比最高的选择。这些高性能的APCA甚至远售欧洲，波兰的骑警就有装备至少20套使用了巷战配置的突击-4，用来对付日益猖狂的赛博格恐怖袭击。偶尔也会有一些退役或战损的突击-4会被去掉大部分附加改件，并改装成工程外骨骼。尽管在工地里的表现比不上正经的工程外骨骼，但经历过战场的淬炼，已足够证明它们的可靠和耐用。"},grp:""},{n:"近卫军-Б",mf:"俄军",type:"重",intro:"巷战终结者，西伯利亚之虎",ra:"R",lore:"",parts:{头部组件:[{n:"Maska 壁垒重盔",mf:"俄军",type:"重",ar:"28",hp:"40",slot:"4",ds:"观察窗式现实界面",pr:5400,ra:"R"},{n:"卡博肖夫战场分析系统",mf:"俄军",type:"中",ar:"20",hp:"30",slot:"6",ds:"全HUD宽幅式",pr:15e3,ra:"SR"},{n:"T-30坦克式监控窗口",mf:"斯通",type:"重",ar:"23",hp:"43",slot:"3",ds:"增强式观察窗",pr:9e3,ra:"R"},{n:"COM-2 小队指挥中枢",mf:"渡微",type:"中",ar:"22",hp:"28",slot:"7",ds:"虚拟实景交互界面，自带无人机链路",pr:45e3,ra:"SSR"}],身体组件:[{n:"近卫军-Б原装框架",mf:"俄军",type:"重",ar:"27",hp:"65",slot:"6",ds:"移动-1，敏捷-1，体格16，整合了快速修复急救系统",pr:33e3,ra:"SR"},{n:"巴罗金 步兵战车装甲",mf:"斯通",type:"重",ar:"30",hp:"80",slot:"5",ds:"移动-1，敏捷-2，体格18，整合了复合合金装甲、逃生舱",pr:49e3,ra:"SR"},{n:"鲍里斯 火力支援框架",mf:"俄军",type:"重",ar:"26",hp:"65",slot:"5",ds:"移动-1，敏捷-2，体格17，整合了复合合金装甲、双联100mm迫击炮（不占背包）",pr:55e3,ra:"SSR"},{n:"TAC-Д突击框架",mf:"吉拉法",type:"中",ar:"22",hp:"55",slot:"7",ds:"敏捷+1，体格14，整合了医疗兵型战场急救装置",pr:44e3,ra:"SSR"}],手部组件:[{n:"近卫军-Б原装外骨骼",mf:"俄军",type:"重",ar:"25",hp:"50",slot:"1",ds:"高级控制，自带武器挂架",pr:1e4,ra:"SR"},{n:"山猫 智能操作臂",mf:"吉拉法",type:"中",ar:"21",hp:"35",slot:"2",ds:"低增强，反应+1",pr:15e3,ra:"SSR"},{n:"巴罗金 边境铁卫",mf:"斯通",type:"重",ar:"24",hp:"45",slot:"1",ds:"高级控制，自带外挂盾牌",pr:12e3,ra:"SR"}],腿部组件:[{n:"近卫军-Б战车轮足",mf:"俄军",type:"重",ar:"24",hp:"47",slot:"2",ds:"移动+1",pr:2e4,ra:"SR"},{n:"巴罗金 液压锚",mf:"俄军",type:"重",ar:"25",hp:"50",slot:"1",ds:"敏捷-1，整合了液压锚，部署后精准额外+1",pr:33e3,ra:"SR"},{n:"EL-PC-4 军工两用框架",mf:"吉拉法",type:"中",ar:"18",hp:"33",slot:"3",ds:"移动+2，敏捷+2",pr:45e3,ra:"SSR"}]},notes:{头部组件:"苏石化为了应对未来的公司战争而设计的重型ACPA，其目的基本上是为了取代现有的步兵支援火力，因此它的设计异常生猛。俄罗斯人不吝惜将步战车级别的护甲叠放到躯干部位，以确保它们在野战中可以与装甲部队对峙的能力。在巷战中，它们会携带重盾和步兵一同推进，并用肩部的武器系统清扫楼内的敌人。苏石化的战斗工兵部队有专门的近卫军编制，在内务部里也有一些用来应对特殊状况。它的外贸版本经常被当作步兵坦克使用，携带夸张的火力，直接担任战场的装甲突击职责。"},grp:""},{n:"标准-C",mf:"荒坂",type:"中",intro:"新标准量产镇暴安保装甲",ra:"R",lore:"",parts:{头部组件:[{n:"浪人-3 增强头盔",mf:"世嘉达利",type:"中",ar:"19",hp:"35",slot:"5",ds:"全HUD宽幅式",pr:17e3,ra:"R"},{n:"标准-B 旧式全息头盔",mf:"世嘉达利",type:"中",ar:"18",hp:"30",slot:"3",ds:"宽幅式观察窗",pr:6e3,ra:"R"},{n:"“青鬼”智能面甲",mf:"甘四郎",type:"轻",ar:"12",hp:"18",slot:"4",ds:"环境计算集成式宽幅HUD，低感态",pr:5700,ra:"SR"},{n:"旗本武士 精锐观瞄系统",mf:"世嘉达利",type:"重",ar:"22",hp:"40",slot:"8",ds:"虚拟实景交互界面，整合了小型电子战天线",pr:3e4,ra:"SSR"}],身体组件:[{n:"标准-C 原装突击框架",mf:"荒坂",type:"中",ar:"21",hp:"45",slot:"6",ds:"体格14，自带合金武士刀，整合了自爆装置、武士道注射器",pr:3e4,ra:"R"},{n:"标准-B 旧式量产装甲",mf:"荒坂",type:"中",ar:"19",hp:"40",slot:"4",ds:"体格14，自带合金武士刀，整合了监护仪",pr:19e3,ra:"R"},{n:"镇暴型防弹框架",mf:"荒坂",type:"轻",ar:"18",hp:"35",slot:"5",ds:"敏捷+1，体格14，整合了监护仪",pr:23e3,ra:"SR"},{n:"用心棒-U 动力框架",mf:"荒坂",type:"中",ar:"22",hp:"45",slot:"6",ds:"敏捷+1，体格14，自带热能武士刀，整合了中继医疗仪",pr:32e3,ra:"SR"},{n:"旗本武士 龙鳞板甲",mf:"三菱",type:"重",ar:"27",hp:"65",slot:"8",ds:"体格17，自带热能野太刀，整合了医疗泡沫封闭系统",pr:5e4,ra:"SSR"}],手部组件:[{n:"标准-C 装甲机械框架",mf:"荒坂",type:"中",ar:"19",hp:"30",slot:"2",ds:"高级控制",pr:8e3,ra:"R"},{n:"标准-B 旧式突击手甲",mf:"荒坂",type:"中",ar:"17",hp:"27",slot:"1",ds:"高级控制",pr:5e3,ra:"R"},{n:"空手道2式镇暴外骨骼",mf:"剑立",type:"轻",ar:"15",hp:"22",slot:"3",ds:"低增强",pr:12e3,ra:"SR"},{n:"旗本武士 决胜突击臂甲",mf:"三菱",type:"重",ar:"24",hp:"38",slot:"2",ds:"低增强，自带高阶武器挂架和热能折叠短刀",pr:21e3,ra:"SSR"}],腿部组件:[{n:"标准-C 机动武士足",mf:"荒坂",type:"中",ar:"19",hp:"30",slot:"2",ds:"移动+2",pr:14e3,ra:"R"},{n:"标准-B 旧式辅助足",mf:"荒坂",type:"中",ar:"17",hp:"27",slot:"1",ds:"移动+1",pr:1e4,ra:"R"},{n:"追击-A 冲锋式轮足",mf:"三菱",type:"轻",ar:"15",hp:"23",slot:"2",ds:"移动+1，敏捷+1，整合了轮式足，奔跑时移动额外+4",pr:13e3,ra:"SR"},{n:"旗本武士 装甲突击外骨骼",mf:"三菱",type:"重",ar:"24",hp:"45",slot:"3",ds:"移动+1",pr:24e3,ra:"SSR"}]},notes:{头部组件:"荒坂的主力ACPA，由第四次公司战争的标准-B改造而来。出于三郎对于近身格斗的喜爱，每一台标准-C都有一个收纳近战刀具的槽位。并且极大特化了近身格斗的能力。它们在野战中的表现不佳，但却是镇暴特警的最爱。由于其经济实惠，维护容易，在各国的军警里都有良好的口碑。其中NCPD就是荒坂的大客户之一。除了警方客户以外，一些帮派份子和安保公司也会购买该款ACPA作为补充火力。一台携带XMA-3B反器材突击步枪的标准-C绝对不是你想在街头看见的对手。"},grp:""},{n:"歼灭-1",mf:"军科",type:"重",intro:"火力平台，步兵的好伙伴",ra:"SR",lore:"",parts:{头部组件:[{n:"精英型空战面板",mf:"轨道航空",type:"中",ar:"22",hp:"35",slot:"5",ds:"环境计算集成式宽幅HUD",pr:21e3,ra:"SR"},{n:"歼灭原型360度监控系统",mf:"军科",type:"重",ar:"25",hp:"40",slot:"6",ds:"宽幅式观察窗",pr:2e4,ra:"R"},{n:"幽魂 电子战头盔",mf:"渡微",type:"中",ar:"20",hp:"30",slot:"6",ds:"全HUD宽幅式，整合了小型电子战天线",pr:32e3,ra:"SR"},{n:"翼手龙中枢指挥系统",mf:"军科",type:"轻",ar:"19",hp:"23",slot:"7",ds:"虚拟实景交互界面",pr:47e3,ra:"SSR"}],身体组件:[{n:"M2 量产野战装甲",mf:"军科",type:"中",ar:"23",hp:"50",slot:"5",ds:"体格14，整合了医疗兵型战场急救装置",pr:31e3,ra:"SR"},{n:"歼灭原型巷战突击框架",mf:"军科",type:"重",ar:"27",hp:"80",slot:"6",ds:"体格16，移动-1，整合了医疗兵型战场急救装置",pr:34e3,ra:"R"},{n:"白头鹰 空中突击框架",mf:"军科",type:"中",ar:"22",hp:"50",slot:"5",ds:"体格14，整合了飞行器",pr:41e3,ra:"SR"},{n:"十字军 机动火炮系统",mf:"军科",type:"重",ar:"28",hp:"70",slot:"4",ds:"体格16，敏捷-1，整合了双联迫击炮背包",pr:53e3,ra:"SSR"}],手部组件:[{n:"歼灭原型重装外骨骼",mf:"军科",type:"重",ar:"21",hp:"40",slot:"2",ds:"低增强",pr:12e3,ra:"R"},{n:"德尔塔机炮辅助臂",mf:"军科",type:"中",ar:"19",hp:"30",slot:"0",ds:"高级控制，整合了高阶武器挂架和一挺BCL-20机炮",pr:19e3,ra:"R"},{n:"龟甲阵 巷战防护臂",mf:"新科",type:"重",ar:"24",hp:"45",slot:"1",ds:"高级控制，整合了外挂盾牌",pr:16e3,ra:"SR"},{n:"克兰顿系列 精确操作臂",mf:"梅塔",type:"中",ar:"18",hp:"28",slot:"3",ds:"高增强",pr:18e3,ra:"SSR"}],腿部组件:[{n:"歼灭原型重装外骨骼",mf:"军科",type:"重",ar:"25",hp:"40",slot:"2",ds:"移动+1",pr:19e3,ra:"R"},{n:"龟甲阵 液压承重腿",mf:"军科",type:"重",ar:"26",hp:"45",slot:"2",ds:"整合了液压锚",pr:2e4,ra:"R"},{n:"歼灭B 反曲机动装置",mf:"军科",type:"中",ar:"20",hp:"30",slot:"1",ds:"移动+1，整合了无动力滑行器",pr:16300,ra:"SR"},{n:"白头鹰 喷气机动腿",mf:"军科",type:"中",ar:"19",hp:"33",slot:"2",ds:"移动+2，整合了硬着陆缓冲装置",pr:17e3,ra:"SR"}]},notes:{头部组件:"在第四次公司战争后，军用科技为了在巷战领域能够和精通近距离作战的荒坂抗衡，特别推出的重型ACPA，不仅在火力全面胜出荒坂的标准系列，在装甲上也要更胜一筹。极大增加了装甲骑兵面对同类敌人的生还率。在军用科技高层的设想中，这款ACPA还可以进行伞降作战，直接落进战区中央，并对周围的敌人倾泻毁灭级的火力。但相对于突击队而言，它的性价比就没有那么美丽了。歼灭系列的外贸成绩一直比不过俄军工的近卫军，因此基本上只有拉撒路佣兵和军用科技自己的部队在使用。"},grp:""},{n:"郊狼",mf:"泽塔",type:"轻",intro:"战场万金油，特种作战专家",ra:"SR",lore:"",parts:{头部组件:[{n:"郊狼原型特战防护头盔",mf:"泽塔",type:"轻",ar:"16",hp:"20",slot:"4",ds:"全HUD宽幅式",pr:12e3,ra:"R"},{n:"螳螂号 侦察头盔",mf:"泽塔",type:"轻",ar:"17",hp:"19",slot:"4",ds:"环境计算集成式宽幅HUD",pr:23e3,ra:"SR"},{n:"COM-2 小队指挥中枢",mf:"渡微",type:"中",ar:"22",hp:"28",slot:"7",ds:"虚拟实景交互界面，自带无人机链路",pr:49e3,ra:"SSR"},{n:"射手座 电子战中枢",mf:"渡微",type:"中",ar:"19",hp:"21",slot:"8",ds:"环境计算集成式宽幅HUD，整合了特种电子战平台",pr:6e4,ra:"SSR"}],身体组件:[{n:"郊狼原型高机动装甲",mf:"泽塔",type:"轻",ar:"18",hp:"43",slot:"6",ds:"体格12，移动+1，整合了快速修复急救系统",pr:22e3,ra:"R"},{n:"IN-4迷彩潜行套装",mf:"泽塔",type:"轻",ar:"17",hp:"40",slot:"7",ds:"体格12，敏捷+1，整合了特种隐身装置和医疗泡沫封闭系统",pr:57e3,ra:"SSR"},{n:"克兰达夫侦察框架",mf:"黛娜拉尔",type:"中",ar:"22",hp:"50",slot:"6",ds:"体格14，整合了喷气背包、医疗兵型战场急救装置",pr:35e3,ra:"SR"},{n:"突破手重型巷战装甲",mf:"军科",type:"重",ar:"26",hp:"65",slot:"8",ds:"体格16，整合了中继医疗仪",pr:41e3,ra:"SR"}],手部组件:[{n:"郊狼原型特战外骨骼",mf:"泽塔",type:"轻",ar:"19",hp:"22",slot:"2",ds:"低增强",pr:11e3,ra:"R"},{n:"突破手巷战武器臂",mf:"军科",type:"重",ar:"23",hp:"30",slot:"1",ds:"高级控制，整合了高级武器挂架",pr:18e3,ra:"SR"},{n:"IN-4低噪音潜行外骨骼",mf:"泽塔",type:"轻",ar:"17",hp:"20",slot:"2",ds:"高增强，潜行+1",pr:2e4,ra:"SSR"}],腿部组件:[{n:"郊狼原型力反馈外骨骼",mf:"泽塔",type:"中",ar:"21",hp:"25",slot:"2",ds:"移动+1，敏捷+1",pr:9e3,ra:"R"},{n:"克兰达夫空降外骨骼",mf:"黛娜拉尔",type:"中",ar:"19",hp:"30",slot:"1",ds:"移动+2，整合了硬着陆缓冲装置",pr:11e3,ra:"SR"},{n:"突破手型巷战外骨骼",mf:"军科",type:"重",ar:"25",hp:"40",slot:"1",ds:"敏捷+1",pr:13e3,ra:"SR"},{n:"IN-4无声反曲足",mf:"泽塔",type:"轻",ar:"17",hp:"20",slot:"2",ds:"移动+1，潜行+4",pr:14e3,ra:"SSR"}]},notes:{头部组件:"一款由泽塔科技推出的特战型ACPA，是渗透作战和伏击的好手。这款ACPA更接近于增强步兵的定位，因此在火力和装甲配置上比较保守。但它足够灵活轻巧，作为空降部队使用时，一台运输机里往往也能塞进更多郊狼。英国的SAS是泽塔科技这个领域的最大客户，他们有一个专门的“狼群”部队全员列装郊狼，以迅捷而致命的姿态执行反恐和镇暴任务。每个人都有专属的职责，并在指挥中枢的调配下达到完美的配合度。在市区里，一支成型的郊狼小队将会是一场噩梦级别的遭遇战。"},grp:""},{n:"大力神",mf:"洛克林",type:"重",intro:"民用科技，土木行业救星",ra:"N",lore:"",parts:{头部组件:[{n:"金星级工程防护头盔",mf:"洛克林",type:"重",ar:"19",hp:"30",slot:"3",ds:"观察窗式现实界面",pr:400,ra:"N"},{n:"分析式作业视窗",mf:"吉拉法",type:"中",ar:"16",hp:"25",slot:"4",ds:"增强式观察窗",pr:700,ra:"R"}],身体组件:[{n:"大力神外机械框架",mf:"洛克林",type:"重",ar:"20",hp:"70",slot:"3",ds:"体格20，敏捷-1，整合了绞盘和抓钩、灭火系统、重型工具架",pr:8e3,ra:"N"},{n:"ECA 工程机装",mf:"吉拉法",type:"中",ar:"16",hp:"50",slot:"4",ds:"体格16，整合了绞盘和抓钩、辅助机械臂",pr:7200,ra:"R"}],手部组件:[{n:"ECA 灵活机械手",mf:"吉拉法",type:"中",ar:"16",hp:"25",slot:"1",ds:"高级控制",pr:2200,ra:"N"},{n:"大力神液压起重臂",mf:"洛克林",type:"重",ar:"15",hp:"40",slot:"0",ds:"基本控制",pr:2e3,ra:"N"}],腿部组件:[{n:"大力神重型支撑框架",mf:"洛克林",type:"重",ar:"15",hp:"40",slot:"1",ds:"移动6，整合了液压锚",pr:3100,ra:"N"}]},notes:{头部组件:"第四次公司战争后的很长一段时间里，有大量废弃的ACPA框架在黑市上流通。一些完全无法在战场上使用的，通常会被改造成工程机械在工地使用。这给了洛克林的高管一个想法，为什么不研发一款工程专用的重型框架呢？于是大力神应运而生。对于军用的APCA来说它过于笨重，基本不会有人考虑用它作为军事用途，但对于街头帮派来说，这是他们能合法搞到的唯一一款ACPA。"},grp:""},{n:"女武神",mf:"渡微",type:"中",intro:"电子战专家，前线指挥支点",ra:"SSR",lore:"",parts:{头部组件:[{n:"女武神原装电子战头盔",mf:"渡微",type:"中",ar:"22",hp:"32",slot:"5",ds:"全HUD宽幅式，算力+1，整合了小型电子战天线",pr:24e3,ra:"SR"},{n:"英灵殿电子战中枢",mf:"EBM",type:"轻",ar:"18",hp:"25",slot:"7",ds:"环境计算集成式宽幅HUD，算力+2，整合了特种电子战平台",pr:57e3,ra:"SSR"},{n:"翼骑兵特勤指挥头盔",mf:"渡微",type:"中",ar:"21",hp:"31",slot:"6",ds:"虚拟实景交互界面，算力+1，整合了无人机链路",pr:45e3,ra:"SSR"}],身体组件:[{n:"女武神原装生存框架",mf:"莱茵金属",type:"中",ar:"23",hp:"56",slot:"5",ds:"体格14，入侵范围提高1km，整合了至高医疗系统、逃生装置",pr:61e3,ra:"SR"},{n:"英灵殿地面预警装甲",mf:"EBM",type:"中",ar:"20",hp:"48",slot:"7",ds:"体格14，入侵范围提高2km，整合了中继医疗仪",pr:81e3,ra:"SR"},{n:"IX-7轻装隐身系统",mf:"渡微",type:"轻",ar:"19",hp:"38",slot:"6",ds:"体格12，潜行+3，整合了特种隐身装置",pr:58e3,ra:"SSR"},{n:"翼骑兵空降突击框架",mf:"轨道航空",type:"重",ar:"25",hp:"62",slot:"4",ds:"体格16，整合了喷气背包+弹药背包",pr:54e3,ra:"SSR"}],手部组件:[{n:"女武神原装突击外骨骼",mf:"阿斯特丽",type:"中",ar:"21",hp:"30",slot:"2",ds:"低增强",pr:11e3,ra:"SR"},{n:"屠龙者重装武器臂",mf:"莱茵金属",type:"重",ar:"26",hp:"40",slot:"1",ds:"低增强,整合了高级武器挂架",pr:18e3,ra:"SR"},{n:"骑士重铠伺服臂",mf:"莱茵金属",type:"中",ar:"22",hp:"32",slot:"2",ds:"高增强",pr:17600,ra:"SSR"},{n:"Z-09实验机装",mf:"阿斯特丽",type:"轻",ar:"18",hp:"27",slot:"4",ds:"超控增强",pr:3e4,ra:"SSR"}],腿部组件:[{n:"女武神高速疾行腿",mf:"洛克林",type:"中",ar:"21",hp:"28",slot:"1",ds:"移动14，整合了动力滑行器",pr:14e3,ra:"SR"},{n:"钢铁支点液压锚",mf:"莱茵金属",type:"重",ar:"27",hp:"45",slot:"1",ds:"整合了液压锚",pr:19e3,ra:"SR"},{n:"Z-011指挥官反曲腿",mf:"洛克林",type:"轻",ar:"19",hp:"20",slot:"2",ds:"移动+2，整合了无动力滑行器",pr:18e3,ra:"SSR"},{n:"翼骑兵空降缓冲腿",mf:"轨道航空",type:"重",ar:"25",hp:"40",slot:"1",ds:"移动12，整合了硬着陆缓冲装置",pr:23e3,ra:"SR"}]},notes:{头部组件:"在长期对正面战场的观察中，渡鸦微控的观察员发现了电子战在前线的广泛应用前景。于是在战后开发了一款专门为小队精英准备的电子战专用指挥型ACPA。相比战场上常见的款式，它的价格几乎能比得上一台主战坦克，但它集成的电子战性能不会让任何指挥官失望。只要有一个足够强大的黑客在驾驭它，几乎就能直接确定一块区域的胜局。"},grp:""},{n:"战隼",mf:"轨航",type:"轻",intro:"翱翔高空的优雅骑士",ra:"SR",lore:"",parts:{头部组件:[{n:"复眼型空战视窗",mf:"轨道航空",type:"轻",ar:"18",hp:"20",slot:"7",ds:"虚拟实景交互界面",pr:4e4,ra:"SR"},{n:"C-21超高空注压头盔",mf:"轨道航空",type:"中",ar:"21",hp:"30",slot:"4",ds:"全HUD宽幅式",pr:28e3,ra:"SR"},{n:"HC-3b重型空战舱",mf:"阿斯特丽",type:"重",ar:"26",hp:"44",slot:"5",ds:"全HUD宽幅式",pr:3e4,ra:"SR"},{n:"战隼原型巡航头盔",mf:"轨道航空",type:"中",ar:"20",hp:"28",slot:"8",ds:"环境计算集成式宽幅HUD",pr:23e3,ra:"SSR"}],身体组件:[{n:"战隼原型滑翔框架",mf:"轨道航空",type:"轻",ar:"18",hp:"40",slot:"5",ds:"体格12，整合了动力滑翔器",pr:3e4,ra:"R"},{n:"战隼-2支援飞行框架",mf:"轨道航空",type:"轻",ar:"19",hp:"44",slot:"4",ds:"体格12，整合了飞行器和喷射引擎",pr:5e4,ra:"SSR"},{n:"R-01轨道突击框架",mf:"阿斯特丽",type:"中",ar:"23",hp:"50",slot:"6",ds:"体格14，整合了喷射引擎",pr:37e3,ra:"SR"},{n:"阿姆斯特朗型生存框架",mf:"轨道航空",type:"重",ar:"27",hp:"60",slot:"7",ds:"体格16，整合了自封闭压缩系统和喷射引擎",pr:47e3,ra:"SSR"}],手部组件:[{n:"战隼原型流线型外骨骼",mf:"轨道航空",type:"轻",ar:"19",hp:"22",slot:"2",ds:"低增强",pr:1e4,ra:"SR"},{n:"SF-02A太空战外骨骼",mf:"阿斯特丽",type:"中",ar:"22",hp:"31",slot:"1",ds:"低增强，整合了高级武器挂架",pr:15e3,ra:"SR"},{n:"P型空降突击臂",mf:"阿斯特丽",type:"重",ar:"26",hp:"41",slot:"1",ds:"高增强，整合了高级武器挂架",pr:21e3,ra:"SSR"}],腿部组件:[{n:"战隼原型滑翔腿",mf:"轨道航空",type:"中",ar:"22",hp:"30",slot:"2",ds:"移动+2，整合了无动力滑行器",pr:13e3,ra:"R"},{n:"R-01轨道突击外骨骼",mf:"阿斯特丽",type:"重",ar:"25",hp:"40",slot:"3",ds:"移动+2，整合了硬着陆缓冲装置，坠落免伤的距离翻倍。",pr:23e3,ra:"SSR"},{n:"德莱塔型反曲滑行腿",mf:"轨道航空",type:"轻",ar:"19",hp:"22",slot:"1",ds:"移动+3，敏捷+1，整合了动力滑行器",pr:15e3,ra:"SR"}]},notes:{头部组件:"一款专门为空降突击作战设计的ACPA，以低空作战的机动性作为主要考量，牺牲了一部分护甲和火力。但同时也为了能在轨道和高空作战，它的基础骨架也可以使用专门设计的重型框架。在轨道航空和高骑士的多次冲突中，它都发挥了相当重要的作用。即便是轨道航空的死对头欧空局也有部分采购，用来维护他们在太空中的财产和利益。"},grp:""},{n:"皇家骑士",mf:"阿斯特丽",type:"中",intro:"殖民地的利刃与坚盾",ra:"SR",lore:"",parts:{头部组件:[{n:"B-3皇家骑士智能系统",mf:"阿斯特丽",type:"中",ar:"22",hp:"30",slot:"5",ds:"环境计算集成式宽幅HUD",pr:43e3,ra:"R"},{n:"COM-CMD渗透感知系统",mf:"渡微",type:"轻",ar:"18",hp:"20",slot:"6",ds:"虚拟实景交互界面,整合了电子干扰指向性天线",pr:5e4,ra:"SSR"},{n:"COM-2 小队指挥中枢",mf:"渡微",type:"中",ar:"22",hp:"28",slot:"7",ds:"虚拟实景交互界面，自带无人机链路",pr:45e3,ra:"SSR"},{n:"HC-3b重型空战舱",mf:"阿斯特丽",type:"重",ar:"26",hp:"44",slot:"5",ds:"全HUD宽幅式",pr:3e4,ra:"SR"}],身体组件:[{n:"B-3皇家骑士战斗装甲",mf:"阿斯特丽",type:"中",ar:"22",hp:"55",slot:"6",ds:"体格15，整合了复合合金装甲、逃生装置",pr:33e3,ra:"R"},{n:"R-01轨道突击框架",mf:"阿斯特丽",type:"中",ar:"23",hp:"50",slot:"6",ds:"体格14，整合了喷射引擎",pr:37e3,ra:"SR"},{n:"COM-CMD渗透装甲",mf:"黛娜拉尔",type:"轻",ar:"17",hp:"30",slot:"6",ds:"体格12，整合了红外迷彩发生器",pr:4e4,ra:"SR"},{n:"夏尔-C型重装陆战框架",mf:"阿斯特丽",type:"重",ar:"28",hp:"65",slot:"5",ds:"体格16，整合了中继医疗仪、逃生装置",pr:43e3,ra:"SSR"}],手部组件:[{n:"B-3皇家骑士智能外骨骼",mf:"阿斯特丽",type:"中",ar:"24",hp:"30",slot:"2",ds:"高级控制，整合了弹药挂架",pr:12e3,ra:"R"},{n:"雷诺-Z智能伺服肌肉臂",mf:"阿斯特丽",type:"轻",ar:"18",hp:"25",slot:"3",ds:"低增强",pr:1e4,ra:"SR"},{n:"P型空降突击臂",mf:"阿斯特丽",type:"重",ar:"26",hp:"41",slot:"1",ds:"高增强，整合了高级武器挂架",pr:21e3,ra:"SSR"}],腿部组件:[{n:"B-3原型皇家骑士战靴",mf:"阿斯特丽",type:"中",ar:"24",hp:"30",slot:"2",ds:"移动+1，整合了无动力滑行器",pr:12e3,ra:"R"},{n:"COM-CMD渗透型无声外骨骼",mf:"阿斯特丽",type:"轻",ar:"18",hp:"25",slot:"2",ds:"移动+2，潜行+2，整合了硬着陆缓冲装置",pr:14e3,ra:"SR"},{n:"R-01轨道突击外骨骼",mf:"阿斯特丽",type:"重",ar:"25",hp:"40",slot:"3",ds:"移动+2，整合了硬着陆缓冲装置，坠落免伤的距离翻倍。",pr:23e3,ra:"SSR"}]},notes:{头部组件:"作为法国特种任务指挥部（COS）和阿斯特丽外籍军团的专用ACPA，皇家骑士是一套昂贵而强大的作战系统。它尽管在装甲上会有所欠缺，但是在智能系统上绝对两大管饱。恨不得将一整个战场态势分析系统和火控系统一起塞进驾驶员的HUD上，这也让它的培训流程较为繁琐。而给这样的装甲进行后勤保养工作更是噩梦般的体验。"},grp:""},{n:"战獒",mf:"塔伦警用",type:"轻",intro:"忠诚,凶猛,永不松口。",ra:"R",lore:"",parts:{头部组件:[{n:"战獒原型多视觉头盔",mf:"塔伦警用",type:"轻",ar:"16",hp:"25",slot:"4",ds:"宽幅式观察窗",pr:6e3,ra:"R"},{n:"牧羊犬-γ型指挥头盔",mf:"世嘉达利",type:"轻",ar:"19",hp:"25",slot:"5",ds:"全HUD宽幅式",pr:9e3,ra:"SR"}],身体组件:[{n:"战獒原型镇暴框架",mf:"塔伦警用",type:"轻",ar:"16",hp:"40",slot:"5",ds:"体格10，整合了绞盘与抓钩",pr:12e3,ra:"R"},{n:"战獒升级款治安框架",mf:"塔伦警用",type:"轻",ar:"18",hp:"45",slot:"6",ds:"体格12，整合了闪光弹发射器",pr:16e3,ra:"R"},{n:"座狼型突击装甲",mf:"黛娜拉尔",type:"中",ar:"22",hp:"45",slot:"6",ds:"体格14，整合了绞盘与抓钩、肩部武器挂架*1",pr:25e3,ra:"SR"}],手部组件:[{n:"战獒原型机械外骨骼",mf:"黛娜拉尔",type:"轻",ar:"16",hp:"21",slot:"6",ds:"基本控制",pr:5e3,ra:"R"},{n:"GA-2街巷扫荡者加特林臂",mf:"塔伦警用",type:"中",ar:"18",hp:"35",slot:"3",ds:"高级控制，自带武器挂架、弹药挂架和碎人者六管加特林",pr:14e3,ra:"SR"},{n:"座狼-∑作战增强臂",mf:"黛娜拉尔",type:"中",ar:"20",hp:"30",slot:"5",ds:"低增强",pr:11e3,ra:"SR"}],腿部组件:[{n:"战獒原型辅助机械腿",mf:"塔伦警用",type:"轻",ar:"16",hp:"30",slot:"1",ds:"移动+1，整合了攀爬器",pr:4e3,ra:"R"},{n:"座狼-∑重型突击足",mf:"黛娜拉尔",type:"中",ar:"20",hp:"35",slot:"1",ds:"移动+2，整合了无动力滑行器",pr:9e3,ra:"SR"}]},notes:{头部组件:"塔伦警用和黛娜拉尔合作研发的新一代镇暴ACPA，在市场上和荒坂的标准系列呈竞争关系。但它更轻，更便宜，性价比也更高。但是作为镇暴装甲，它难以担当军用ACPA的重任，即便是重装配置，在战场上的生存性能也并不理想。但它在各国军警中十分受欢迎，一些第三世界国家也会采购它作为军队的ACPA。毕竟，他们的经费本就十分捉襟见肘。"},grp:""},{n:"忠胜",mf:"荒坂",type:"",intro:"赛博格决战兵器，大鬼后继者",ra:"",lore:"",parts:{头部组件:[{n:"忠臣藏驾驶员生存舱",mf:"荒坂",type:"重",ar:"28",hp:"50",slot:"/",ds:"虚拟实景交互界面，反应14，意志20，其自带系统如下： 激光通讯器 智能武器上行链路 雷达辐射感应器 电子对抗系统 巷战雷达 磁强计 智能索敌锁定系统 整合型战场火控装置",pr:"/",ra:"/"}],身体组件:[{n:"鬼王级突破框架",mf:"三菱",type:"重",ar:"31",hp:"80",slot:"/",ds:"体格18，四肢被报废时不会伤害到驾驶员。其自带系统如下： 重型肩部武器挂架（携带BHC-G8 57mm线膛炮） 闪光弹发射器 复合合金装甲 肩部火箭巢（携带微型火箭巢） 喷气背包+弹药背包 自动装弹系统 重型探照灯 纳米自修复系统 自爆装置 “武士道”兴奋剂注射器 医疗泡沫封闭系统",pr:"/",ra:"/"}],手部组件:[{n:"武藏号粉碎重臂",mf:"荒坂",type:"重",ar:"26",hp:"45",slot:"/",ds:"超控增强，其自带系统如下： 高级武器挂架（携带40MM榴弹机枪） 热能野太刀 液压锤 左右手各持一把ONI-特攻型自动霰弹枪（使用特供镖弹）",pr:"/",ra:"/"}],腿部组件:[{n:"八岐大蛇反曲突击足",mf:"三菱",type:"重",ar:"26",hp:"50",slot:"/",ds:"移动+3，敏捷+2，其自带系统如下： 动力滑行器 硬着陆缓冲装置 喷射引擎",pr:"/",ra:"/"}]},notes:{头部组件:"自从2023年，亚当重锤驾驶着“大鬼”ACPA落败于黑手之后，荒坂开始考虑研发一款比“大鬼”更加强大的ACPA。在这种思维下，“忠胜”诞生了。它是一款在各个性能都做到极致的“决战兵器”，为了能够加装更多装甲和功能性部件，荒坂的设计师直接放弃了为驾驶员提供的活动空间，因此只有一个被削掉四肢和下半身的赛博格才能被塞进那个专属的驾驶舱里。在新荒坂塔的建成典礼上，一台“忠胜”就站在三郎身边，为他提供护卫。有传言声称里面的驾驶员就是亚当·重锤的克隆体。2046年，一位荒坂高管叛逃，来到中美洲的一处军用科技设施里。那处设施里有5台突击-4 ACPA，10辆泰坦装甲车，2台猎犬轻型坦克，以及大约一个连的人在里面把守。在一夜的激烈交火后，那位荒坂高管和基地里的所有士兵都变成了一滩肉泥，而从那天晚上士兵们在通讯频道的哭嚎来看，荒坂在那一夜里，只出动了一架“忠胜”。"},grp:"特殊装甲（实验款/非卖品）"},{n:"歼灭-2A",mf:"军科",type:"",intro:"反龙骑兵专用框架，单兵坦克",ra:"",lore:"",parts:{头部组件:[{n:"P-99式脑链实境头盔",mf:"军科",type:"超重",ar:"26",hp:"45",slot:"/",ds:"虚拟实景交互界面，其自带系统如下： 智能武器上行链路 雷达辐射感应器 雷达 磁强计 长距智能火控计算机 整合型战场火控装置 小型电子战天线",pr:"/",ra:"/"}],身体组件:[{n:"歼灭-2A spvm3 坦克框架",mf:"军科",type:"超重",ar:"38",hp:"90",slot:"/",ds:"体格24，直到被摧毁之前都是坦克级护甲，其自带系统如下： 烟雾弹发射器 逃生装置 灭火系统 弹药背包 自动装弹系统 AGAM加特林近防系统 肩部重炮系统（携带EAP-80 磁轨滑膛炮） 反应装甲*2",pr:"/",ra:"/"}],手部组件:[{n:"克林格式重装反馈武器臂",mf:"军科",type:"超重",ar:"25",hp:"50",slot:"/",ds:"高增强，其自带系统如下： 高级武器挂架（左手携带EMG-25 重型磁轨炮，右手携带BCL-20 车用机炮） 反应装甲 手榴弹抛射装置",pr:"/",ra:"/"}],腿部组件:[{n:"PAF101式空降突击足",mf:"军科",type:"超重",ar:"24",hp:"60",slot:"/",ds:"移动+1，敏捷+1，其自带系统如下： 硬着陆缓冲装置 履带足 反应装甲",pr:"/",ra:"/"}]},notes:{头部组件:"在中国战场和欧洲战场上，军用科技遭遇了许多次IEC的龙骑兵赛博格部队。它们不仅有着比突击队ACPA更加灵活的性能，还有更强大的反应能力和武器系统。在IEC建立的一体化信息指挥链之下，它们可以比军用科技培训的大头笔更有效率地进行作战，往往可以歼灭多于自己数量的ACPA小队，这一现实让军用科技的高层头疼不已。在IEC推出新款龙骑兵后，他们再也不能坐视不理，开发了一款几乎可以算是主战坦克的超重型ACPA，歼灭-2A有四个人的高度，其腿部在需要的时候可以折叠成履带在公路上飞驰，还能进行空降打击，用身上的武器系统歼灭所见的一切敌人。即便是面对现役的主战坦克，也能不落下风。能使用这种ACPA的装甲骑兵往往也是王牌中的王牌。拉撒路佣兵曾在东南亚用一台歼灭-2A面对一支成型的龙骑兵小队，并在无损失的情况下将对方全歼。一度让IEC的领导层产生了恐慌，并着手新型龙骑兵的开发计划。"},grp:"特殊装甲（实验款/非卖品）"},{n:"赛博妖鬼",mf:"泽塔科技",type:"",intro:"AI辅助，人机合一",ra:"",lore:"",parts:{头部组件:[{n:"巫妖式精神融合匣",mf:"泽塔科技",type:"中",ar:"22",hp:"40",slot:"/",ds:"虚拟实景交互界面，反应16，智力18，意志20，其自带系统如下： 智能武器上行链路 雷达辐射感应器 无人机上行链路 电子对抗系统 特种电子战平台（可以同时对四个目标进行快速入侵） 巷战雷达 智能索敌锁定系统 磁强计 整合型战场火控装置",pr:"/",ra:"/"}],身体组件:[{n:"不朽式封闭压缩舱",mf:"泽塔科技",type:"中",ar:"25",hp:"60",slot:"/",ds:"体格14，其自带系统如下： 翼手龙桑德威斯坦（见义体表，开启后可以闪避子弹） 液态子宫舱 自封闭压缩系统 弹药背包+无人机背包 光学迷彩发生器 自动装弹系统 飞行器 自爆装置 特种隐身装置",pr:"/",ra:"/"}],手部组件:[{n:"阿瑞斯机动武器臂",mf:"泽塔科技",type:"中",ar:"24",hp:"33",slot:"/",ds:"超控增强，其自带系统如下： 高级武器挂架（左手携带HKS70 特战突击步枪，右手携带碎人者六管加特林） 单分子剑 手榴弹抛射装置",pr:"/",ra:"/"},{n:"鬼灵智控臂",mf:"泽塔科技",type:"轻",ar:"18",hp:"22",slot:"/",ds:"超控增强，额外多出的两只手，可以使用武术。其自带系统如下： 单分子剑 各持用一把使用穿甲弹的忠诚僚机手枪。",pr:"",ra:""}],腿部组件:[{n:"幽灵式无声潜入足",mf:"泽塔科技",type:"中",ar:"24",hp:"40",slot:"/",ds:"移动+4，敏捷+2，其自带系统如下： 攀爬器 喷射引擎 动力滑行器",pr:"/",ra:"/"}]},notes:{头部组件:"泽塔科技在很早以前就开始了对流窜AI和相关技术的研究，他们的特工小队在全球四处出击，在网络监察之前偷偷抓走了不少高危的人工智能，并通过研究它们，掌握了将AI与人脑意识体结合的技术。但可惜的是，这项技术不仅不可逆，而且相当不稳定。因此泽塔科技只用这套技术造了几台实验型号。但令研究人员感到恐惧的是，这几台试验型号在所有方面的表现都大大超乎了他们的预期，2043年，泽塔科技曾经调动了两个排的郊狼小队前去阿肯色州的机密实验室，有小道消息称，就是因为一台“赛博妖鬼”发生了暴走事件。不仅附近三个镇子都突然没了信号，同一时间还有大约100人同时发作了赛博精神病。这一事件让泽塔科技废了好一番功夫，才成功平息。"},grp:"特殊装甲（实验款/非卖品）"}],acpaMods:[{n:"观察窗式现实界面",mf:"/",part:"头",bonus:"先攻-3，反应-1",ds:"这种最简单的型号依赖于头盔上的开口，由防弹玻璃或塑料保护，这样骑兵就可以看到外界了。 这种极其低效的方式将骑兵的视野限制在与中世纪骑士差不多的水平。",ra:"N",slot:"-1",pr:-700,grp:"现实交互界面系统",sub:""},{n:"增强式观察窗",mf:"/",part:"头",bonus:"先攻-1，反应-1",ds:"增强式观察窗仅仅是指在动力服上增加了有限的镜头和/或音频接收器。 虽然很难说是足够的，但标准红外线夜视仪或微光夜视仪设备的可靠性能让骑兵的处境稍微好一些。从这个级别开始，所有的界面都提供了关于动力装甲系统当前状态的HUD。整合了基础通讯链路",ra:"R",slot:"/",pr:1e3,grp:"现实交互界面系统",sub:""},{n:"宽幅式观察窗",mf:"/",part:"头",bonus:"无",ds:"宽幅式增强了增强式观察窗有限的附加功能，最显著的是镜头排列，从根本上改善了骑兵的周边视野。它还包括一些简单的瞄准辅助，很像智能护目镜。虽然前文中更简单的观察窗式系统要先进得多，但扭曲的宽幅图像看起来又累又麻烦。整合了基础通讯链路、微光夜视仪",ra:"R",slot:"/",pr:3e3,grp:"现实交互界面系统",sub:""},{n:"全HUD宽幅式",mf:"/",part:"头",bonus:"先攻+1",ds:"除了提高宽幅图像的质量外，全HUD还增加了一个自动瞄准和目标采集系统，使骑兵的武器装备反应更灵敏，更致命，并允许串联的多个武器用一个动作开火。在这个级别上，全封闭头盔的缺点终于被消除了。整合了基础通讯链路、防护眩光、微光夜视仪和图像增强。",ra:"SR",slot:"1",pr:7500,grp:"现实交互界面系统",sub:""},{n:"环境计算集成式宽幅HUD",mf:"/",part:"头",bonus:"先攻+1，反应+1",ds:"虽然学习使用有些困难，但这种宽幅HUD增加了计算能力，使骑兵能够解析周围地形的几何特征。 距离、角度、反射等，都以符号的形式展现给骑兵，如果信息有价值的话，则以图形的形式展现。有了ECI（即环境计算集成式）HUD，骑兵开始在使用动力服的卓越性能方面得到一些辅助。整合了防护眩光、红外线夜视仪、图像增强、望远镜和拾音降噪侦测系统",ra:"SSR",slot:"1",pr:1e4,grp:"现实交互界面系统",sub:""},{n:"虚拟实景交互界面",mf:"/",part:"头",bonus:"先攻+2，反应+2",ds:"爽飙装甲的唯一方式，虚拟实境界面为装甲骑兵解析他所处的环境，并以复杂的图形和有限的听觉警告向他展示信息。 在这一级的系统上，驾驶动力装甲与进行网跑已没有什么区别。熟练的装甲骑兵在装备此系统后将变得极为致命。整合了防护眩光、激光夜视仪、远程瞄准、热成像、图像增强、卫星上行链路、多目标瞄准系统和拾音降噪侦测系统",ra:"SSR",slot:"2",pr:16e3,grp:"现实交互界面系统",sub:""},{n:"基本控制",mf:"/",part:"手臂",bonus:"反应-1",ds:'这是一个 "傻瓜式 "的系统，由大多数非战斗型或实用型动力装甲使用。这也是所有民用（和少数军用）线性框架上使用的系统。基本控制系统在任何情况下都不会违反人体的可动范围。这意味着驾驶员操作时的最大反应为8。',ra:"N",slot:"-1",pr:-500,grp:"反射/控制系统",sub:""},{n:"高级控制",mf:"/",part:"手臂",bonus:"无",ds:"军用ACPA的标准系统。 它允许驾驶员发挥出满额的反应，最高为10。",ra:"R",slot:"1",pr:0,grp:"反射/控制系统",sub:""},{n:"低增强",mf:"/",part:"手臂",bonus:"敏捷+1",ds:'该系统通过一个简化的"狗脑"式AI处理器监测所有主动和非主动的肌肉活动。 它使驾驶员在操作ACPA时可发挥的反应最高为11。它还允许动力装甲的穿戴者使用他的武术技能',ra:"SR",slot:"1",pr:5200,grp:"反射/控制系统",sub:""},{n:"高增强",mf:"/",part:"手臂",bonus:"敏捷+2",ds:"它让操纵者能控制全方位的神经肌肉功能，并与现实交互界面（必须是宽幅式观察窗或更高等级）协调，以调节所有感官输入信号的优先级。驾驶员可以保持充分的警觉性和完全的注意力，长达12小时；然后他可以进行一个提振精神的快速眼动睡眠，持续60分钟。它还允许动力装甲的穿戴者使用他的武术技能",ra:"SR",slot:"1",pr:6700,grp:"反射/控制系统",sub:""},{n:"超控增强",mf:"/",part:"手臂",bonus:"反应+1，敏捷+3",ds:"这个实验性的系统必须要使用者进行神经探针改造才能使用。能让体内神经以接近光速进行反应，并让高效能的仿生肌肉束协同肢体，就像龙骑兵赛博格一样。在近身攻击时，武器的ROF+1，拳脚的ROF+2。这种系统不能安装在重型框架上。它还允许动力装甲的穿戴者使用他的武术技能",ra:"SSR",slot:"1",pr:1e4,grp:"反射/控制系统",sub:""},{n:"监护仪",mf:"/",part:"躯干",bonus:"无",ds:"按照西方的标准，这是一个最低限度的系统，它可进行最多四次可控制的药物注射。 此外，如果骑兵将陷入昏迷或死亡，动力服会向特殊的接收设备进行一次1分钟的单射频无线电传输广播，详细说明骑兵的状态。最后，自动医疗系统配有一个归航信标，将保持激活并准确定位骑兵的位置1D6小时。",ra:"N",slot:"1",pr:300,grp:"自动医疗",sub:""},{n:"“武士道”兴奋剂注射器",mf:"荒坂",part:"躯干",bonus:"无",ds:"这套简陋的系统实际上并不能让驾驶员活下来，只是能让他活着。它里面配备了两种特制的兴奋剂，一种在战斗中注射，另一种在驾驶员遭到重创时注射。前者是臭名昭著的黑蕾丝，而后者则是令人恐惧的“飙血者”。它可以让驾驶员保持极度兴奋状态，无视身上的伤口和疼痛，继续驾驶直到失血过多而死。而它也会如其名字一样加速驾驶员的流血速度。许多报告显示重创的荒坂装甲骑兵会在临死前爆发出惊人的战斗力，是无数军科士兵的噩梦。",ra:"N",slot:"1",pr:600,grp:"自动医疗",sub:""},{n:"快速修复急救系统",mf:"俄军工",part:"躯干",bonus:"死豁-1",ds:"最基本的系统，快速修复最多可以容纳三种不同的药物，一般通过注射的方式来使用。虽然快速修复中实际上可以容纳多种剂量的药物，但通常一次使用时只可以注射一种战斗或治疗药物。这些药物可以被手动激活注射；每种药物都有单独的触发器。快速修复也可以被设置为在内置监测器检测到骑兵失去意识时，自动使用一种或多种药物。",ra:"R",slot:"1",pr:1100,grp:"自动医疗",sub:""},{n:"医疗兵型战场急救装置",mf:"军用科技",part:"躯干",bonus:"战场急救+1",ds:"标准的自动医疗系统，承重生命出品的医疗兵装置可以配备多达五种不同的药物，用户可以根据自己的详细情况进行预设。医疗兵装置提供与荒坂监护仪相同的通知和信标功能，不同的是，信号的接收者可以多次要求重新传输骑兵的状态信息，直到信标能源耗尽。然而，医疗兵系统最值得一提的是它的体表压迫阵列，可编程的、可膨胀的套筒围绕着骑兵的四肢和躯干。当医疗兵装置检测到血压下降或伤口出血时，它可以智能地让适当位置上的套筒膨胀来压迫止血。",ra:"R",slot:"1",pr:1400,grp:"自动医疗",sub:""},{n:"中继医疗仪",mf:"军用科技",part:"躯干",bonus:"战场急救+1， 死豁-2",ds:'军科推出的大型、昂贵和广为宣传的自动医疗装置即为中继仪。基本上与承重生命的医疗兵系统相似，中继仪的药物容量能配备7种药物，是一个勉强称得上是宝贵的东西。它最著名的是它的 "对话诊断师?"，一个语音激活的，封闭于装甲中的，微型计算机，允许骑兵询问他的动力服对他目前的医疗状况有什么最好的办法。无关紧要的一点是，骑兵被允许选择自动医疗系统“人格”的语音类型和"名字"。中继仪的压迫装置比承重生命医疗兵系统的要贵一些。有了中继仪，所有重骰的眩晕或死亡豁免都会得到+2的加值，大大增加了装甲骑兵的生存机会。',ra:"SR",slot:"1",pr:2e3,grp:"自动医疗",sub:""},{n:"医疗泡沫封闭系统",mf:"泽塔科技",part:"躯干",bonus:"战场急救+2 死豁-4",ds:"可以在应急时刻为装甲骑兵封闭伤口止血的装置，可以自动帮助装甲骑兵稳定伤势，通过死亡豁免。（两次后失效）在装甲骑兵本人遭受伤害时，它会自动喷射医疗泡沫封闭伤口，并及时止血。使驾驶员受到的一切来源的伤害-3。",ra:"SR",slot:"1",pr:2500,grp:"自动医疗",sub:""},{n:"至高医疗系统",mf:"轨道航空",part:"躯干",bonus:"战场急救+4",ds:'至高，一个真正的小型化奇迹，与军科的中继仪功能相同，只是它在空间利用上更高效。轨道航空贴心地给他们所有的骑兵配备了至高医疗系统，有些人认为，该设备的建造只是为了羞辱军科，这与轨道航空的新格言一致，"无论你能做什么，我们都能做得更小！"。在驾驶员HP归零且溢出的伤害小于其体格时，自动通过死亡豁免并让驾驶员可以在没有重伤的DEBUFF下保持行动一回合。驾驶员本身受到一切来源的伤害减半。',ra:"SSR",slot:"1",pr:4e3,grp:"自动医疗",sub:""},{n:"自爆装置",mf:"荒坂",part:"躯干",bonus:"无",ds:"这是一个臭名远扬的装置，为了不让公司机密落入敌手，在装甲躯体报废时，或是侦测到驾驶员无生命迹象时，它将会设定在10秒后自爆。对周围10m的任何目标造成6D8点破片伤害。装甲骑士此时若还活着，可以用一个动作从装甲中脱离出来。也可以在未报废时手动引发此装置。由于这个系统是纯机械装置，黑客无法以任何方式入侵它。",ra:"N",slot:"1",pr:700,grp:"安全系统",sub:""},{n:"逃生装置",mf:"/",part:"躯干",bonus:"无",ds:'物超所值，逃生舱门是一个 "装置"，包括爆炸性螺栓，一个微处理器，一个大型电容器，以及ACPA本体上精妙的割接处。 当动力服受到损害而倒下，并且/或者因此关机后，电容器将激发一个或多个智能引导的爆炸物，使动力服被翻转到正面。然后螺栓爆炸，打开头盔，肩膀和上身，使驾驶员可以只用一个动作就轻松脱身。',ra:"N",slot:"1",pr:600,grp:"安全系统",sub:""},{n:"自封闭压缩系统",mf:"/",part:"躯干",bonus:"无",ds:"是真空或水下作业的必需品。 虽然所有的ACPA至少都有相当的气密性和水密性，但如果没有自封式压缩系统，它们在无气或高压环境中仍不是彻底安全的。有了这个系统，装甲骑兵可以在真空中，或在最深750米的水中正常操作。 如果要使用一台真正的飞行装置，也需要这个系统。当动力服受到伤害时，这个系统通常可以在液体密封剂耗尽前封上3D6个破洞。如果驾驶员要在这样的环境中停留超过一个小时，就需要扩展生命支持系统。这个选项所需的空间可以分布在整套装甲上。",ra:"R",slot:"2",pr:4e3,grp:"安全系统",sub:""},{n:"喂食/过滤系统",mf:"/",part:"躯干",bonus:"无",ds:"这是一个臭名远扬的装置，它的设计目的是让骑兵在战场条件下坚持最多2天半，且不停下来获取口粮或排泄。 该装置确实容易造成身体孔隙的磨损和偶尔的轻微炎症。 该选项可以置于任何部位的空间。",ra:"R",slot:"1",pr:400,grp:"安全系统",sub:""},{n:"扩展生命支持",mf:"/",part:"躯干",bonus:"无",ds:"在外太空、水下或真实飞行下的动力装甲必备。每4小时单位的生命维持系统就占据1点空间。可以是位于躯干或腿部的封闭/外部系统。",ra:"R",slot:"1",pr:600,grp:"安全系统",sub:""},{n:"额外动力电池",mf:"/",part:"躯干",bonus:"无",ds:"使装甲在极端环境中活动的时间增加24小时。",ra:"R",slot:"1",pr:800,grp:"安全系统",sub:""},{n:"液态子宫舱",mf:"泽塔科技",part:"躯干",bonus:"无",ds:"用可呼吸的特制溶氧液填满驾驶空间，用来减轻战斗时产生的震动。但因此穿脱时间要比平常多一分钟。当躯体的护甲被穿透后造成的伤害减半。生效两次。之后系统报废。",ra:"SR",slot:"2",pr:6e3,grp:"安全系统",sub:""},{n:"基础通讯链路",mf:"/",part:"头",bonus:"无",ds:"标准无线电，不占空间",ra:"N",slot:"0",pr:30,grp:"视听、通信和特殊传感器",sub:""},{n:"卫星上行链路",mf:"/",part:"头",bonus:"无",ds:"允许动力装甲直接与轨道上的通信或侦察卫星连接，并在露天野外区域保持通讯信号良好。",ra:"R",slot:"1",pr:170,grp:"视听、通信和特殊传感器",sub:""},{n:"无人机上行链路",mf:"/",part:"头",bonus:"无",ds:"能和一台无人机建立连接，若在指挥它行动时还在进行其他动作，则驾驶员和无人机的任意检定都-4。",ra:"R",slot:"1",pr:600,grp:"视听、通信和特殊传感器",sub:""},{n:"蜂窝电话",mf:"/",part:"头",bonus:"无",ds:"一个普通的蜂窝系统，但具有更远的范围（可以从20公里的距离连接到城市网络）。 如果没有中继站，就不能在地下或山区工作。",ra:"R",slot:"1",pr:500,grp:"视听、通信和特殊传感器",sub:""},{n:"扰频器",mf:"/",part:"头",bonus:"无",ds:"与上述四个选项兼容，扰频器允许加密通信，其他动力服只有同样配备了扰频器，并有正确的扰频器密码组合才能解读。再花500欧元，扰频器可以配备一个处理器，有20%几率会给出正确的密码组合，以此可监听截获的对话。",ra:"SR",slot:"1",pr:600,grp:"视听、通信和特殊传感器",sub:""},{n:"激光通讯器",mf:"/",part:"头",bonus:"无",ds:'点对点的通讯方式，它允许动力装甲在视线范围内与另一个装有类似设备的动力服进行通讯。 它不能被干扰，只能通过让装有激光通讯器的动力服用阻断光束（破坏通讯）的方式进行 "窃听"。',ra:"SR",slot:"1",pr:650,grp:"视听、通信和特殊传感器",sub:""},{n:"感官延申",mf:"/",part:"躯干/手臂/头",bonus:"无",ds:"这相当于ACPA的赛博改造系统。这些天线安装了摄像头和拾音器，可以从转角后探出来，将图像传送给驾驶员，而不用将整个动力服暴露在敌人的火力之下。战斗服的交互界面必须至少是宽幅式观察窗才能正确使用这些扩展装置。 平均长度为0.66米。 只能挂载于手臂、躯干或头部空间的外部。",ra:"SR",slot:"1",pr:500,grp:"视听、通信和特殊传感器",sub:""},{n:"智能武器上行链路",mf:"/",part:"头",bonus:"无",ds:"将身上的武器系统链接至头部显示器，可以直接用弹道的方式进行瞄准，而不需要凭借武器本身的瞄具。需要武器上有智能链接，你瞄准50m以内的任何目标都取射击DV表的最小值。",ra:"R",slot:"1",pr:1300,grp:"视听、通信和特殊传感器",sub:""},{n:"长距智能火控计算机",mf:"/",part:"头",bonus:"无",ds:"攻击401m~1km的目标时，使用的DV为射击DV表中第三小的数值。",ra:"SR",slot:"1",pr:4500,grp:"视听、通信和特殊传感器",sub:""},{n:"多目标瞄准系统",mf:"/",part:"头",bonus:"无",ds:"可以将多件已链接的进攻系统/手持武器整合进自己战斗动作的一部分。但本回合每多用一件武器，命中就额外-2。",ra:"SR",slot:"1",pr:2500,grp:"视听、通信和特殊传感器",sub:""},{n:"拾音降噪侦测系统",mf:"/",part:"头",bonus:"察觉（听）+2",ds:"能精确识别并过滤战场上的噪音，从中分拣出有用的信息。可以听见最远70米外的细微动静。",ra:"SR",slot:"1",pr:200,grp:"视听、通信和特殊传感器",sub:""},{n:"整合型战场火控装置",mf:"/",part:"头",bonus:"精准度+1",ds:"具备多目标瞄准系统功能，和智能索敌锁定系统冲突。若整合的武器系统中带有需要锁定的武器，则免去锁定需要的动作。",ra:"SSR",slot:"1",pr:5e3,grp:"视听、通信和特殊传感器",sub:""},{n:"智能索敌锁定系统",mf:"/",part:"头",bonus:"无",ds:"具备多目标瞄准系统功能，和整合型战场火控装置冲突。可以让肩部的一个武器系统花费一个移动动作锁定敌人，即便该武器原本没有锁定射击功能。锁定后必定命中。",ra:"SSR",slot:"1",pr:6e3,grp:"视听、通信和特殊传感器",sub:""},{n:"远程瞄准",mf:"/",part:"头",bonus:"无",ds:"提供最远5km的望远功能，并可以通过智能武器上传链路提供弹道瞄准。",ra:"SR",slot:"1",pr:700,grp:"视听、通信和特殊传感器",sub:""},{n:"防护炫光",mf:"/",part:"头",bonus:"无",ds:"免疫闪光弹和高功率手电筒的影响。",ra:"N",slot:"1",pr:200,grp:"视听、通信和特殊传感器",sub:""},{n:"微光夜视仪",mf:"/",part:"头",bonus:"无",ds:"提供夜视功能，在微光环境下可视距离100m，无光环境30m。",ra:"N",slot:"1",pr:150,grp:"视听、通信和特殊传感器",sub:""},{n:"红外线夜视仪",mf:"/",part:"头",bonus:"无",ds:"提供夜视功能，在微光和无光环境下可视距离1km，并可以看见红外信号。",ra:"R",slot:"1",pr:300,grp:"视听、通信和特殊传感器",sub:""},{n:"激光夜视仪",mf:"/",part:"头",bonus:"无",ds:"提供夜视功能，在微光和无光环境下可视距离3km，并可以看见红外信号。",ra:"SR",slot:"1",pr:600,grp:"视听、通信和特殊传感器",sub:""},{n:"热成像",mf:"/",part:"头",bonus:"无",ds:"提供热成像视觉功能，可以探测2km内的热能信号，并反馈在视觉上。可以穿透常规烟雾，不能穿透硬物。",ra:"SR",slot:"1",pr:1e3,grp:"视听、通信和特殊传感器",sub:""},{n:"望远镜",mf:"/",part:"头",bonus:"无",ds:"可以进行变焦放大，最远可以放大至64x。进行远距离侦察时的绝妙帮手。",ra:"N",slot:"1",pr:300,grp:"视听、通信和特殊传感器",sub:""},{n:"图像增强",mf:"/",part:"头",bonus:"先攻+1",ds:'配有更宽的观察区域和 "快速变焦"，觉察系技能出1可重骰一次。',ra:"SR",slot:"1",pr:1e3,grp:"视听、通信和特殊传感器",sub:""},{n:"可见光",mf:"/",part:"头",bonus:"无",ds:"这只是基础可见光监视器的一个备份，在主要交互装置（增强式观察窗或更高级）发生故障的情况下，它可提供相当于无视觉升级选项的增强式观察窗的图像。",ra:"R",slot:"1",pr:100,grp:"视听、通信和特殊传感器",sub:""},{n:"音视频记录仪",mf:"/",part:"头",bonus:"无",ds:"就像一个多媒体录像机，这个记录仪通过装甲骑兵的ACPA主要感官输入，可以在一个数字芯片上记录最多6个小时的数据。装置可容纳两个芯片。",ra:"R",slot:"1",pr:50,grp:"视听、通信和特殊传感器",sub:""},{n:"雷达",mf:"/",part:"头",bonus:"无",ds:"只要没有其他物体阻挡信号，雷达就能探测到10公里范围内的物体。 雷达可以被干扰。",ra:"SR",slot:"1",pr:7500,grp:"视听、通信和特殊传感器",sub:""},{n:"雷达辐射感应器",mf:"/",part:"全身任意",bonus:"无",ds:"能在雷达范围内侦测一切开机的雷达，并定位出雷达的大致方向。距离雷达越近，精确度越高，甚至可以直接探测雷达的具体距离。",ra:"SR",slot:"1",pr:2800,grp:"视听、通信和特殊传感器",sub:""},{n:"巷战雷达",mf:"/",part:"头",bonus:"无",ds:"专门为巷战使用的穿墙雷达，可以穿过一切阻挡探测100米范围内的活物和机械信号。雷达可以被干扰。",ra:"SSR",slot:"1",pr:12e3,grp:"视听、通信和特殊传感器",sub:""},{n:"声纳",mf:"/",part:"头",bonus:"无",ds:"声波发射/探测系统为动力装甲提供了声纳功能，能够探测50米内的固体物体。 它只能被大量的聚焦噪声（爆炸，车载白噪声发生器等）干扰。如果声纳没有开启主动式搜索，它可以通过枪式扩展麦克风监听200米范围内特定的声音。",ra:"SR",slot:"1",pr:2700,grp:"视听、通信和特殊传感器",sub:""},{n:"磁强计",mf:"/",part:"头",bonus:"无",ds:'也被称为磁异常探测器，该装置可以探测700米内的大块金属。在城市环境下不是很有用，但在郊区会是探测隐藏载具或ACPA的好方法。磁强计在探测轨道炮方面非常出色，可以在武器的3倍射程内探测到轨道炮发射时产生的磁场 "尖峰 "。',ra:"SR",slot:"1",pr:6e3,grp:"视听、通信和特殊传感器",sub:""},{n:"攀爬器",mf:"/",part:"腿部",bonus:"无",ds:"附着于足部的高摩擦力磁能装置，可以用来攀爬任何坚固的表面。使用者每回合能攀爬等于自己移动米数的垂直表面。",ra:"R",slot:"1",pr:450,grp:"运动系统",sub:""},{n:"喷射引擎",mf:"/",part:"腿部",bonus:"无",ds:"一组重型喷射引擎。需要花费一个移动动作开启。开启后使用者的移动力固定为14，并可进行任意方向，乃至垂直的机动。持续三回合",ra:"SR",slot:"1",pr:1700,grp:"运动系统",sub:""},{n:"滑翔器",mf:"/",part:"躯干",bonus:"无",ds:"这个装置是一个巨大的，机械化的，制造工艺令人惊异的可伸缩滑翔翼。除了从悬崖和高楼逃生外就没有多少其他用途了。滑翔器需要2轮的时间来伸展，3轮的时间才能收回。当使用时，骑兵每回合可以以三米的速度缓慢下降，并在此过程中Mov+4。滞空滑行态势下，敌方命中难度你的增加2。",ra:"SR",slot:"1",pr:1700,grp:"运动系统",sub:""},{n:"剃刀足",mf:"/",part:"腿部",bonus:"无",ds:"在足部加装致命的单分子刀片，在进行近战攻击时获得额外的1ROF，数值同动力甲拳击，但伤害增加1D6。无法安装在重型框架上。",ra:"R",slot:"1",pr:600,grp:"运动系统",sub:""},{n:"飞行器",mf:"/",part:"躯干",bonus:"SDP+10",ds:"终极飞行系统，引擎和框架技术来自EEC的蛇龙级巡航导弹的脉冲喷气引擎，由IEC设计。可以在短暂助跑后（一回合移动12mov以上）起飞至最高30m的离地高度（每回合最多爬升10m），并在这个过程中保持18mov，其燃料可以支持ACPA以此态势滞空5回合，之后会以每回合3m的速度缓慢下降。在飞行态势下，敌方命中你的难度增加3，滞空滑行态势下，命中难度增加2。",ra:"SSR",slot:"1",pr:3700,grp:"运动系统",sub:""},{n:"动力滑行器",mf:"/",part:"腿部",bonus:"移动+1",ds:"这些可伸缩的、有动力的溜冰鞋允许一名装甲骑兵以接近117km/h(移动力20)的速度在铺装路面上飞驰。做任何形式的转弯或刹车都需要使用地面载具驾驶技能进行DV20+难度的机动检定。",ra:"SSR",slot:"2",pr:1900,grp:"运动系统",sub:""},{n:"全向动力轮",mf:"/",part:"腿部",bonus:"移动+1",ds:"移动+2，只能安装在轻型ACPA身上，这种极其灵敏的全向轮可以在熟练的装甲骑兵手上达到极其夸张的机动性。使ACPA可以闪避200m外朝其射击的火力。",ra:"SSR",slot:"2",pr:3e3,grp:"运动系统",sub:""},{n:"无动力滑行器",mf:"/",part:"腿部",bonus:"无",ds:"这些无动力的伸缩式溜冰鞋可以让一个装甲骑兵在良好的路面上（如公路、桥梁）奔跑的移动力翻倍。",ra:"SR",slot:"1",pr:1100,grp:"运动系统",sub:""},{n:"轮式足",mf:"/",part:"腿部",bonus:"敏捷+1",ds:"可以折叠的全向滑行轮，不可与履带足兼容，在奔跑时额外获得+4移动。在公路上进行机动时+6移动，并视为具有80km/h最高时速的载具。",ra:"N",slot:"1",pr:500,grp:"运动系统",sub:""},{n:"履带足",mf:"/",part:"腿部",bonus:"sp+1",ds:"附着于腿部的装甲履带，不可与轮式足兼容，在奔跑时额外获得+2移动。在公路上进行机动时+4移动，并视为具有60km/h最高时速的载具。",ra:"N",slot:"1",pr:600,grp:"运动系统",sub:""},{n:"硬着陆缓冲装置",mf:"/",part:"腿部",bonus:"SDP+5",ds:"允许使用者从18m的高度坠落时不承受任何伤害，18m以上的坠落伤害也减半进行计算。",ra:"N",slot:"2",pr:850,grp:"运动系统",sub:""},{n:"绞盘和抓钩",mf:"/",part:"躯干",bonus:"无",ds:"这是一个越简单越有用的系统，它包括一个强大的、装有弹簧的抓钩发射管。大约50米长的细长钢缆被连接至抓钩，允许装甲骑兵把它作为承重线或摆荡线发射出去。装甲骑兵可以向上发射并使用绞盘作为快速升降机，或从下面拉起物品。偶尔，一个大胆的装甲骑兵会给自己配备几个绳索和抓取装置，让自己能从一个建筑荡到另一个建筑，在他走的时候把绳索留下。",ra:"N",slot:"1",pr:100,grp:"通用系统",sub:""},{n:"自动装弹系统",mf:"/",part:"躯干",bonus:"无",ds:"必须要有弹药挂架或者弹药背包。可以使武器直接从挂架或背包上自动填补弹药，而无需手动换弹。武器的弹容量变更为身上包括备用弹匣的总弹容量。",ra:"R",slot:"1",pr:2e3,grp:"通用系统",sub:""},{n:"弹药挂架",mf:"/",part:"躯干",bonus:"无",ds:"基础弹药存储设备，为ACPA的主要武器系统提供两个弹匣的弹容量（如果是单发装填武器或火箭弹、导弹，则提供四发），为副武器系统提供一个弹匣的弹容量（如果是单发装填武器或火箭弹、导弹，则提供两发）。最多只能为两个武器系统提供弹药，可重复安装，但每个重复安装的该系统只能为一个武器提供一个弹匣的弹药。",ra:"N",slot:"1",pr:200,grp:"通用系统",sub:""},{n:"液压锚",mf:"/",part:"腿部",bonus:"无",ds:"安置在腿部的固定式液压锚，不能安装在轻型腿部上。可以在发射重型武器的时候减轻武器的后坐力。驾驶员可以用一个移动动作部署在原地，这样使用越级武器不再会有惩罚，用非越级武器时候精准度+2。需要双腿一起安装，且效果只会不会叠加。",ra:"R",slot:"1",pr:500,grp:"通用系统",sub:""},{n:"灭火系统",mf:"/",part:"躯干",bonus:"无",ds:"二氧化碳/泡沫系统，可扑灭ACPA外部的起火物质，也可用于扑灭小型火灾（直径不超过2米），重注前可用4次。",ra:"R",slot:"1",pr:150,grp:"通用系统",sub:""},{n:"重型探照灯",mf:"/",part:"躯干",bonus:"无",ds:"装在一个灵活支架上的外部探照灯。该灯可被作为一个目标瞄准。探照灯光可以是白光，红外，或紫外光。可见光型号可以作为手枪武器使用，但不会造成伤害，只会使对手致盲。最大范围为200米。如果目标被击中，目标在三回合的时间里将会承受“目盲”严重伤势，除非安装了防炫光。",ra:"SR",slot:"1",pr:270,grp:"通用系统",sub:""},{n:"纳米自修复系统",mf:"/",part:"躯干",bonus:"无",ds:"一套由编程式纳米蜂群和液态金属原料组成的系统，可以在战场上及时对受损部位进行修补。每回合能恢复部位2点SDP，全身最多恢复20点。",ra:"SSR",slot:"1",pr:1e4,grp:"通用系统",sub:""},{n:"重型工具套件",mf:"/",part:"躯干",bonus:"无",ds:"包含了许多备用零件甚至装甲板，用以在战场上对损坏部位进行及时迅捷的维修。可花费十分钟将已损坏的系统恢复至1耐久，也可以再花费半小时将耐久恢复至一半。",ra:"R",slot:"2",pr:680,grp:"通用系统",sub:""},{n:"轻型工具套件",mf:"/",part:"躯干",bonus:"无",ds:"用以在战场上对损坏部位进行及时迅捷的维修。可花费十分钟将已损坏的部位恢复至1耐久，也可以再花费十分钟恢复至四分之一耐久（取整）",ra:"N",slot:"2",pr:300,grp:"通用系统",sub:""},{n:"紧急维修套件",mf:"/",part:"躯干",bonus:"无",ds:"用以在战场上对损坏部位进行及时迅捷的维修。可花费十分钟将已损坏的部位恢复至1耐久，但只能使用一次。",ra:"N",slot:"1",pr:150,grp:"通用系统",sub:""},{n:"辅助机械臂",mf:"/",part:"躯干",bonus:"无",ds:"在肩部增加一个辅助的机械臂，有人手大小。可用来持握重物或者步兵枪械。最多持握重型冲锋枪。用此方式持握的额外武器精度-3.",ra:"R",slot:"1",pr:750,grp:"通用系统",sub:""},{n:"折叠收容盒",mf:"/",part:"躯干",bonus:"无",ds:"增加一个额外的收容空间，可使改造数量+1，也可以用来存放额外的轻型ACPA武装。但同时会减少2点部位sp，并可能会导致护甲等级下降。",ra:"N",slot:"/",pr:500,grp:"通用系统",sub:""},{n:"微型反应堆装置",mf:"/",part:"背包",bonus:"无",ds:"提供双倍的燃料/能量上限，并使ACPA的续航时间翻倍。",ra:"N",slot:"背包",pr:600,grp:"背包",sub:""},{n:"额外生命维持装置",mf:"/",part:"背包",bonus:"无",ds:"可以让使用者在无氧环境下呼吸额外10小时。",ra:"R",slot:"背包",pr:800,grp:"背包",sub:""},{n:"无人机背包",mf:"/",part:"背包",bonus:"无",ds:"内含一个中型无人机槽位/四个小型无人机槽位，需要无人机上行链路才能与携带的无人机互动。",ra:"SR",slot:"背包",pr:1800,grp:"背包",sub:""},{n:"喷气背包",mf:"/",part:"背包",bonus:"无",ds:"可以使用其跳跃至多13m的高度，冷却时间三回合。",ra:"SR",slot:"背包",pr:2700,grp:"背包",sub:""},{n:"弹药背包",mf:"/",part:"背包",bonus:"无",ds:"为ACPA的主要武器系统提供四个弹匣的弹容量（如果是单发装填的武器或火箭弹、导弹，则提供八发）。为副武器系统提供两个弹匣的弹容量（如果是单发装填的武器或火箭弹、导弹，则提供四发）。最多可以为三个武器系统提供弹药，第三个武器系统也视为副武器。和自动装弹系统配合，可以使装备者身上携带的所有武器无需在战斗中换弹。",ra:"N",slot:"背包",pr:1500,grp:"背包",sub:""},{n:"重型电子战天线背包",mf:"/",part:"背包",bonus:"无",ds:"强大的军用电子战系统，极其昂贵。可以对半径3km以内的任意信号源发动电子战/快速入侵攻击。视作一位拥有3赛博技术，等级6的网行者。有6个魔偶插槽。网行者使用时，除非使用者是网行者，否则无法用此部件进入赛博空间。若和其他电子战系统搭配，则可以将入侵距离提升至7km。电子战详情参考下方小型电子战天线。",ra:"SSR",slot:"背包",pr:6e3,grp:"背包",sub:""},{n:"光学迷彩发生器",mf:"/",part:"背包",bonus:"潜行+4",ds:"以一个动作开启，在三回合内进入肉眼隐身状态。冷却时间一分钟。潜行+5。仍然会被安装了热成像、超声波、雷达或红外线的敌人感应到。",ra:"SR",slot:"背包",pr:8e3,grp:"背包",sub:""},{n:"重型电子屏蔽背包",mf:"/",part:"背包",bonus:"/",ds:"自带一个小型电子战天线，同时可以干扰侦测你的雷达和各种电子设备。雷达侦测你时，会在100m范围内侦测到10个目标。当一枚导弹锁定你时，你投掷一枚D10，骰出6+，该导弹将脱离锁定。",ra:"SR",slot:"背包",pr:"",grp:"背包",sub:""},{n:"特种隐身装置",mf:"/",part:"背包",bonus:"潜行+6",ds:"以一个动作开启，在一分钟内进入光学+红外隐身状态，冷却时间五分钟。开启时，无法被任何侦测手段感应到。但会在强光和淋水下失效。",ra:"SSR",slot:"背包",pr:12e3,grp:"背包",sub:""},{n:"单分子爪",mf:"/",part:"手臂",bonus:"无",ds:"数据同猛禽之爪，但伤害额外加一粒骰子",ra:"N",slot:"1",pr:100,grp:"进攻系统",sub:""},{n:"折叠短刀",mf:"/",part:"手臂",bonus:"无",ds:"数据同单分子短刀，但伤害额外加一粒骰子",ra:"N",slot:"1",pr:170,grp:"进攻系统",sub:""},{n:"液压锤",mf:"/",part:"手臂",bonus:"无",ds:"数据同爆破锤，但伤害额外加一粒骰子",ra:"R",slot:"1",pr:1e3,grp:"进攻系统",sub:""},{n:"液压长矛",mf:"/",part:"手臂",bonus:"无",ds:"数据同立旗伸缩矛，但伤害额外加一粒骰子",ra:"R",slot:"1",pr:550,grp:"进攻系统",sub:""},{n:"动力链锯",mf:"/",part:"手臂",bonus:"无",ds:"数据同长刃链锯。但护甲损伤额外+1",ra:"SR",slot:"1",pr:1100,grp:"进攻系统",sub:""},{n:"加热重剑",mf:"/",part:"手臂",bonus:"无",ds:"数据同热切刃，但伤害额外加1粒骰子，且穿甲等级上升一级。",ra:"SR",slot:"1",pr:2e3,grp:"进攻系统",sub:""},{n:"液压重拳",mf:"/",part:"手臂",bonus:"无",ds:"拳击力度增加1D6，不能和武器挂架共存。可以和高级武器挂架共存。",ra:"SR",slot:"1",pr:1800,grp:"进攻系统",sub:""},{n:"合金武士刀",mf:"荒坂",part:"手臂",bonus:"无",ds:"数据同单分子太刀，但伤害额外加1粒骰子.",ra:"R",slot:"1",pr:700,grp:"进攻系统",sub:""},{n:"热能武士刀",mf:"荒坂",part:"手臂",bonus:"无",ds:"数据同热能武士刀，但伤害额外加2粒骰子，且拥有重反器材级别的穿甲能力",ra:"SR",slot:"1",pr:2300,grp:"进攻系统",sub:""},{n:"热能野太刀",mf:"荒坂",part:"躯干",bonus:"无",ds:"数据同热能野太刀，但伤害额外加2粒骰子，且拥有反坦克级别的穿甲能力",ra:"SSR",slot:"2",pr:3100,grp:"进攻系统",sub:""},{n:"工业切割激光",mf:"梅塔",part:"手臂",bonus:"无",ds:"数据同聚焦采矿激光，只能安装在重型框架上。",ra:"SSR",slot:"2",pr:4300,grp:"进攻系统",sub:""},{n:"手榴弹抛射装置",mf:"/",part:"手臂",bonus:"无",ds:"一种抛射步兵手榴弹的装置，可以将任意手榴弹装填进去发射。它的数据同M-205榴弹发射器，但爆炸后的效果取决于用它投掷的手榴弹。",ra:"R",slot:"1",pr:700,grp:"进攻系统",sub:""},{n:"微型火箭弹射装置",mf:"IEC",part:"手臂",bonus:"无",ds:"为新款龙骑兵准备的反坦克系统，内含一发串联HEAT破甲火箭弹，可重复装填，但射程只有400m。",ra:"SR",slot:"1",pr:1200,grp:"进攻系统",sub:""},{n:"小型武器挂架",mf:"/",part:"手臂",bonus:"无",ds:"可以安装在任何手臂上，使ACPA可以在手上额外加装一套步兵武器系统。不可用来安装盾牌，只能安装非重武器和狙击步枪的非ACPA武器。",ra:"N",slot:"1",pr:700,grp:"进攻系统",sub:""},{n:"武器挂架",mf:"/",part:"手臂",bonus:"无",ds:"只能安装在中型和重型手臂上，使ACPA可以在手上额外加装一把轻型ACPA武器。",ra:"R",slot:"1",pr:1e3,grp:"进攻系统",sub:""},{n:"高阶武器挂架",mf:"/",part:"手臂",bonus:"无",ds:"只能安装在重型手臂上，使ACPA可以在手上额外加装一把中型ACPA武器。也可以用来安装盾牌，但安装了盾牌之后将无法使用原本的机械手。",ra:"SR",slot:"2",pr:1300,grp:"进攻系统",sub:""},{n:"肩部武器挂架",mf:"/",part:"躯干",bonus:"无",ds:"安装在肩部的武器挂架，最多安装两个，可以额外使用一把步兵武器或中型ACPA武器。肩部安装的武器若不搭配智能武器上行链路使用，则会在命中上承受-3的减值。",ra:"SR",slot:"1",pr:1100,grp:"进攻系统",sub:""},{n:"重型肩部武器挂架",mf:"/",part:"躯干",bonus:"敏捷-1",ds:"安装在肩部的武器挂架，最多安装两个，只能安装在重型ACPA躯体上。可以搭载一门重型ACPA武器。肩部安装的武器若不搭配智能武器上行链路使用，则会在命中上承受-3的减值。",ra:"SSR",slot:"2",pr:1800,grp:"进攻系统",sub:""},{n:"60mm迫击炮背包",mf:"/",part:"背包",bonus:"敏捷-2",ds:"安装在背部的60mm军用迫击炮装置，和背包冲突。本身携带了10发60mm迫击炮弹药。迫击炮数据详见下表。",ra:"SR",slot:"1",pr:2e3,grp:"进攻系统",sub:""},{n:"双联100mm迫击炮背包",mf:"俄军工",part:"背包",bonus:"敏捷-3",ds:"安装在背部的双联100mm迫击炮系统，和背包冲突，本身携带了6发100mm迫击炮弹药。只能安装在重型ACPA上。迫击炮数据详见下表。",ra:"SSR",slot:"2",pr:3e3,grp:"进攻系统",sub:""},{n:"肩部重炮系统",mf:"/",part:"躯干",bonus:"敏捷-2",ds:"安装在肩部的重型磁轨炮系统，只能安装在重型框架上。同时附带一个强大的蓄电装置，和背包冲突。发射8发弹药后电源耗尽。肩部安装的武器若不搭配智能武器上行链路使用，则会在命中上承受-3的减值。只能安装一个。磁轨炮数据详见下表。",ra:"SSR",slot:"2",pr:9800,grp:"进攻系统",sub:""},{n:"肩部火箭巢",mf:"/",part:"躯干",bonus:"敏捷-2",ds:"安装在肩部的重型火箭巢.通常安装多重微型火箭，也可以替换为其他的单兵火箭或者导弹装置。详见下表",ra:"SSR",slot:"2",pr:2700,grp:"进攻系统",sub:""},{n:"外装盾牌",mf:"/",part:"手臂",bonus:"敏捷-1",ds:"数据同巷战壁垒，在装甲的正面提供防护。和武器挂架冲突。",ra:"N",slot:"1",pr:1e3,grp:"防御系统",sub:""},{n:"反红外隐身涂料",mf:"/",part:"特殊",bonus:"无",ds:"使雷达和热成像侦测你的距离减少一半。",ra:"N",slot:"/",pr:800,grp:"防御系统",sub:""},{n:"低感态",mf:"/",part:"特殊",bonus:"/",ds:"随机部位骰出该部位时，需要重新投掷一次。只有两次同样确认命中该部位，才会被击中。不可加装，只是特性。",ra:"N",slot:"/",pr:"/",grp:"防御系统",sub:""},{n:"反应装甲",mf:"/",part:"全身任意",bonus:"sp+1",ds:"增加1点部位SP，若一次破甲后的伤害大于20，则免疫这一次伤害，并让本系统报废。可重复加装，但额外加装的反应装甲不会叠加SP。",ra:"N",slot:"1",pr:200,grp:"防御系统",sub:""},{n:"复合合金装甲",mf:"/",part:"躯干",bonus:"敏捷-1",ds:"获得5点减伤，面对高级穿甲能力的伤害来源时失效（例如反坦克伤害作用在装甲车护甲上时）。只能安装在中型/重型框架上。",ra:"R",slot:"2",pr:1e3,grp:"防御系统",sub:""},{n:"外置装甲笼",mf:"/",part:"躯干",bonus:"无",ds:"只能安装在中型/重型框架上，使火箭弹或者导弹的直射伤害减半。生效两次后本系统报废。",ra:"N",slot:"1",pr:600,grp:"防御系统",sub:""},{n:"钢化陶瓷面甲",mf:"/",part:"头部",bonus:"SDP+1",ds:"让头部的护甲临时上升一个等级，被一次半穿级以上的火力贯穿后，该系统失效。",ra:"R",slot:"1",pr:500,grp:"防御系统",sub:""},{n:"电子干扰指向性天线",mf:"IEC",part:"头/躯干/手",bonus:"/",ds:"每回合一次，干扰一发锁定你的导弹，使其脱离锁定并偏离。无法干扰无制导火箭弹，只能安装一次。",ra:"SR",slot:"1",pr:2e3,grp:"防御系统",sub:""},{n:"小型电子战天线",mf:"/",part:"头部/躯干",bonus:"无",ds:"可以让使用者在500m距离内干扰、入侵敌方电子设备。视作一位拥有3赛博技术，等级4的网行者，有三个魔偶插槽，若使用者本身是网行者则可以使用自己的数据代替检定。若使用者不是网行者则无法用此潜入赛博空间。在选定目标后，使用者每回合可使用一次免费的网络行动来进行入侵检定。下方列表皆是民用设备的难度，若是军用或是公司的特殊设备，则DV难度额外+1~5 小型设备（手机、电视、电脑、无线电、摄像头）DV8， 重型设备（天线、服务器、汽车、低级人工智能）DV12, 高科技设备（人工智能，干扰天线、雷达、植入体、敌方网行者）DV16",ra:"SR",slot:"1",pr:3e3,grp:"防御系统",sub:""},{n:"特种电子战平台",mf:"/",part:"头部/躯干",bonus:"反应-1",ds:"同小型电子战天线，但距离有2km，相当于一位拥有5赛博技术，等级6的网行者。有五个魔偶插槽，若使用者本身是网行者，则可以让其交互界面检定+2，网络行动+2，算力+5。",ra:"SSR",slot:"2",pr:11230,grp:"防御系统",sub:""},{n:"烟雾弹发射器",mf:"/",part:"躯干",bonus:"无",ds:"在被导弹锁定时，自动在周身范围内投射反红外烟雾，半径6m，红外视觉和热成像无法看穿，以激光、红外、热感、图像方式进行锁定的导弹将无法命中。只有一发存弹量，该系统可以重复安装。",ra:"N",slot:"1",pr:500,grp:"防御系统",sub:""},{n:"电子对抗系统",mf:"/",part:"头部",bonus:"无",ds:"对抗敌方电子战系统的干扰时，你的DV+2",ra:"R",slot:"1",pr:2400,grp:"防御系统",sub:""},{n:"闪光弹发射器",mf:"/",part:"躯干",bonus:"无",ds:"在前方30m范围内投射一颗高能震撼弹。一共有四发存弹量。",ra:"R",slot:"1",pr:1800,grp:"防御系统",sub:""},{n:"红外迷彩发生器",mf:"/",part:"躯干",bonus:"无",ds:"以一个动作开启，在三回合内进入肉眼隐身状态，潜行+5，不会被感应红外和热成像看见，但是会被雷达发现。冷却时间一分钟。",ra:"SR",slot:"1",pr:4400,grp:"防御系统",sub:""},{n:"投石索主动防御系统",mf:"阿斯特丽",part:"躯干",bonus:"无",ds:"一种轻型的主动防御系统，会占据一个肩部的武器槽。使用特制的40mm近射霰弹对来袭火箭和导弹进行拦截。由于射角有限且射速较慢，拦截效率不算很高，但在应急时刻也算是一种救命手段。当雷达侦测到来袭目标时，投掷一枚D10，出目6+成功拦截，只能拦截火箭弹和导弹，无法拦截炮弹。该系统可以被多个射弹所迷惑。当受到多枚导弹袭击时，每多出一枚导弹，拦截的难度便+1。",ra:"SR",slot:"2",pr:5e3,grp:"防御系统",sub:""},{n:"AGAM加特林近防系统",mf:"军用科技",part:"躯干",bonus:"无",ds:'占用一个肩膀槽位，"迷你密集阵 "是一种反导弹武备（基于.22加特林机枪设计），类似于舰载的宙斯盾保护系统。系统会追踪来袭的导弹或火箭，自动瞄准目标，并尝试在该目标击中装甲骑兵前将其摧毁或引爆。如果火箭或导弹射向受AGAMS保护的ACPA，系统将会检测到它并立刻拦截。（D10掷出4+出目）；一旦探测到目标，系统会在100m或以下的范围内进行拦截；AGAMS可以被多个射弹所迷惑。当受到多枚导弹袭击时，每多出一枚导弹，拦截的难度便+1。',ra:"SSR",slot:"3",pr:12300,grp:"防御系统",sub:""},{n:"武器系统",mf:"射速（全自动）",part:"类型",bonus:"弹容（弹药）",ds:"描述",ra:"精准",slot:"伤害",pr:"穿甲等级",grp:"防御系统",sub:""},{n:"宪法军工 .50重机枪",mf:"（3）（5）",part:"机枪（轻）",bonus:"100（.50BMG）",ds:"重机枪 最常见的ACPA武装之一，有大量的遗留库存，因此价格十分实惠。通常是固定在吉普车上的自卫武器。可以被轻型ACPA双手持握，也可以安装在重型ACPA的手臂上。",ra:"0",slot:"/",pr:"轻反器材",grp:"防御系统",sub:""},{n:"斯通博文 KPV-pa重机枪",mf:"3（5）",part:"机枪（中）",bonus:"50（14.5mm）",ds:"重机枪 14.5*114mm的重机枪，初速和精度高，穿甲性能优越。美中不足的是其弹容量低，通常使用时以点射为主。攻击目标时，先减去对方3sp，再对剩下的护甲进行计算。",ra:"1",slot:"6D10+4",pr:"轻反器材",grp:"防御系统",sub:""},{n:"军科 碎人者六管加特林",mf:"（5）（7）",part:"机枪（轻）",bonus:"400（7.62全）",ds:"机枪 通常安装在载具和ACPA身上的轻型加特林，不推荐由单兵携带。但由于其夸张的射速，往往需要搭配一个足够大的弹药背包为其供弹。其每种射击方式使用的弹药是原本的三倍，所有射击模式敌方闪避-6。对掩体伤害翻倍。必须体格10以上才可以使用。加特林的扫射最高可指定相当于长点射的目标（此武器为7）",ra:"0",slot:"/",pr:"全威力",grp:"防御系统",sub:""},{n:"RKG-022 高空突击炮",mf:"3（4）",part:"机炮（轻）",bonus:"40（20mm火箭）",ds:"机炮 轨道航空的ACPA小队会在高空轨道中使用的火箭推进机炮。它的弹长较短，更依赖火箭进行加速。这使得它的初速略低，但它的后座力相比来说也很容易被轻型框架承受。它50m以上的射程精度+1，且可以在该距离无视目标的4sp。弹药价格是普通机炮弹药的1.5倍。",ra:"0",slot:"6D12",pr:"轻反器材",grp:"防御系统",sub:""},{n:"EMG-25 重型磁轨炮",mf:"2",part:"狙击（重）",bonus:"20（30mm磁）",ds:"机炮 弹链供弹的重型磁轨机炮，使用30mm钨芯磁轨穿甲弹，穿甲性能和精度极其优越。美中不足的是，它的后效不足，没法对内部组件造成有效杀伤。因此通常推荐对薄弱部位进行打击。计算护甲穿透时，先减去10的SP，再对剩下的护甲进行减半处理。",ra:"1",slot:"5D10",pr:"反坦克",grp:"防御系统",sub:""},{n:"EAP-80 磁轨滑膛炮",mf:"1",part:"狙击（重）",bonus:"1（80mm磁）",ds:"加农炮 单发装填的重型磁轨炮，只能通过肩部磁轨重炮系统安装，是ACPA能携带的最强大的反坦克武器之一。中型ACPA使用时必须用液压锚固定在硬表面上。它的备弹最多只能携带8发。计算护甲穿透时，先减去10SP，再对剩下的护甲进行减半处理。弹药价格400eb一发。",ra:"2",slot:"10D12+5",pr:"反坦克",grp:"防御系统",sub:""},{n:"梅塔 厄普兰-37狙击炮",mf:"1",part:"狙击（中）",bonus:"10（37mm）",ds:"狙击枪 使用弹匣供弹的37mm口径轻量化机炮，会被一些轻中型ACPA携带，作为远距离支援火力使用。和常规的机炮不同，它使用了更高精度的重型炮管和可以部署的支架。虽然它的火力续航和压制力较差，但它的精度极高。它除了基础的APFSDS弹头（重反器材，忽视5sp，7D10伤害）以外，还有HE（同40mm榴弹，但伤害+2粒骰）弹头。它的弹药价格等同重反器材弹药价格。",ra:"3",slot:"7D10+3",pr:"重反器材",grp:"防御系统",sub:""},{n:"梅塔 埃姆斯-伊兰激光炮",mf:"1~7",part:"重武（重）",bonus:"50(激光电容)",ds:"机炮 梅塔集团研发的高能激光炮，可以在有效距离内造成恐怖的穿甲杀伤。但它不能持续射击太长时间，其内置的保险可以保证这把武器在融化它的聚焦晶体前停下并冷却。在两回合内射击10次ROF将会导致这把武器过热，需要冷却一回合才能继续使用。在计算0~150m距离的护甲穿透时，它可以无视所有的护甲。151~250m的护甲减半，251m以上正常结算。它不能应用任何种类的特殊弹药。",ra:"3",slot:"3d8",pr:"重反器材",grp:"防御系统",sub:""},{n:"BCL-20 车用机炮",mf:"3（4）",part:"重武（中）",bonus:"30（20mm）",ds:"机炮 市面上常见的中口径机炮，是现代步兵战车的标配。一些轻量化的版本也会给ACPA使用，但大大削减了载弹量。",ra:"0",slot:"7d10",pr:"轻反器材",grp:"防御系统",sub:""},{n:"BHC-G8 57mm线膛炮",mf:"2",part:"重武（重）",bonus:"6（57mmAT）",ds:"速射炮 目前为止威力最大的速射炮之一，通常作为肩部唯一的武器系统，或是由重型ACPA双手持用。它的威力足以威胁到旧式坦克，但它最常用的用途是使用编程炮弹进行防空。攻击目标时，先减去对方5sp，再对剩下的护甲进行计算。其地面射程为1km，对空射程可以达到6km。它的防空用编程近炸弹头也可以对地（10m半径造成6D10重反器材伤害）",ra:"0",slot:"7D12",pr:"重反器材",grp:"防御系统",sub:""},{n:"XMA-3b 超重型突击步枪",mf:"3（4）",part:"突击（中）",bonus:"45（.50BMG）",ds:"突击步枪 一款马洛里安专门为ACPA设计的突击步枪。它有使用全威力弹药和反器材弹药的两种款式，但反器材款式在市面上最为常见。是一款性能良好，可靠性极佳,泛用性极广的标配武器。就算轻型ACPA或者穿戴线性框架的步兵，也可以持用它奔赴战场。",ra:"0",slot:"6D10",pr:"轻反器材",grp:"防御系统",sub:""},{n:"HKS70 特战突击步枪",mf:"3（5）",part:"突击（轻）",bonus:"60（11mm-pa磁）",ds:"突击步枪 HK专门为特种行动研发的消音反器材突击步枪，设计紧凑，可以折叠。甚至能作为副武器使用。其使用的11mm无壳磁轨镖弹(轻反器材弹药，价格为200eb 10发)有着极佳的穿甲性能，在充能模式下甚至可以进行穿墙打击。由于其使用的特殊原理，在发射的时候几乎可以做到完全无声，但这是以射程作为代价的。它可以切换至低射速高充能模式，在这个模式下，其ROF每回合只有2，但伤害骰+1，且穿甲等级升级为重反器材武器。",ra:"1",slot:"6D10+2",pr:"轻反器材",grp:"防御系统",sub:""},{n:"G-997 赛博格步枪",mf:"3（5）",part:"突击（中）",bonus:"75（11mm-pa磁）",ds:"突击步枪 IEC为龙骑兵部队设计的标配突击步枪，采用了激进的无壳磁轨镖弹(轻反器材弹药，价格为200eb 10发)，在拥有惊人射速的同时，其后坐力也较为可控。尽管它的弹头看起来平平无奇，但却可以轻易撕碎步兵战车的装甲，也可以轻而易举地摧毁其他轻装甲和软目标。它也可以切换至低射速高充能模式，在这个模式下，其ROF每回合只有2，但伤害骰+1，且穿甲等级升级为重反器材。",ra:"1",slot:"6D10+2",pr:"轻反器材",grp:"防御系统",sub:""},{n:"ATAC-37 磁轨突击炮",mf:"1",part:"突击（重）",bonus:"15（37mmAT）",ds:"速射炮 配备了钨芯尾翼稳定穿甲弹的突击炮，通常需要两手共持才能使用。也会作为肩部的唯一武器系统安装在重型ACPA的身上。它也能发射高爆弹药，对楼房里的驻军造成破片杀伤。其高爆弹范围等同于40mm HE榴弹，但伤害为5d12。",ra:"0",slot:"6D12",pr:"重反器材",grp:"防御系统",sub:""},{n:"莱茵金属C-88手持加农炮",mf:"1",part:"重武（重）",bonus:"1（88mm）",ds:"加农炮 旧式的坦克和步兵战车常用的主炮款式，经过一番改造后，可以作为手提或者肩置的武器系统进行发射。它几乎算是ACPA可以装备的最大口径直射火炮，具备优良的弹道性能和强大的穿甲能力。但在现代由导弹、无人机和磁轨炮主宰的战场上，它严格来说已经“落伍”了。即便如此，在不少第三世界佣兵和三四线部队里，这样的大口径火炮还是一种相当受欢迎的选择。它可以使用常规破甲弹和HE弹头（同反坦克导弹HE弹，但是最大范围减少5m）只能安装智能链接",ra:"0",slot:"10D12",pr:"反坦克",grp:"防御系统",sub:""},{n:"荒坂 三零式无后座炮",mf:"1",part:"重武（中）",bonus:"1（83mmAT）",ds:"无后座炮 标准系列常用的轻型无后座炮，是荒坂对抗敌对装甲部队的主力武器，通常以肩扛方式发射。弹药类型和效果同单兵火炮弹药。只能安装瞄具和智能链接。",ra:"0",slot:"6D12+5",pr:"反坦克",grp:"防御系统",sub:""},{n:"IFAR-8 火箭突击炮",mf:"1",part:"重武（重）",bonus:"4（火箭弹）",ds:"无后座炮 发射火箭弹药和导弹的大口径无后座炮，战场上的装甲克星。通常会被安装在肩膀的武器系统上，少数时候由轻型ACPA携带，如同步兵一样肩扛发射。弹药类型和效果同单兵火箭弹。只能安装智能链接",ra:"1",slot:"6D12",pr:"重反器材",grp:"防御系统",sub:""},{n:"俄军工40MM榴弹机枪",mf:"3",part:"重武（中）",bonus:"25（40mm榴弹）",ds:"榴弹 巷战时的ACPA标配支援武器，比大口径机枪和机炮更适合在巷战环境下进行火力支援。即便在对抗装甲单位的遭遇战中，也有一战之力。只 能安装智能链接",ra:"0",slot:"5D8",pr:"轻反器材",grp:"防御系统",sub:""},{n:"LAS100 四联导弹发射器",mf:"2",part:"重武（中）",bonus:"4（AT导弹）",ds:"导弹 发射激光制导的四联导弹巢，发射时可以使用包括移动动作在内的整个回合进行锁定，使本次射击的精准+3。也可以像发射火箭弹一样关闭引导直射，但会失去精准度加成。",ra:"0",slot:"10D10",pr:"反坦克",grp:"防御系统",sub:""},{n:"IEC 微型导弹巢",mf:"3",part:"重武（中）",bonus:"15（微型导弹）",ds:"导弹 可以用一个动作进行红外信号锁定发射的微型导弹巢，锁定后必定命中目标。除了赛博格和装甲、载具目标以外，也可以锁定普通人。是IEC龙骑兵的标配武装，但无论如何只能安装在肩部。弹药价格和属性同火箭弹，但HE弹头的作用范围减少2m。可以同时发射多枚弹头进行火力覆盖。",ra:"0",slot:"5D12",pr:"重反器材",grp:"防御系统",sub:""},{n:"杰里科 二联装导弹发射器",mf:"1",part:"重武（重）",bonus:"2（AT导弹）",ds:"导弹 发射雷达锁定攻顶导弹的二联导弹巢，需要花费一个动作对雷达上出现的目标进行锁定，锁定后必定命中目标。伤害比普通反坦克导弹+2粒骰子，价格也高400eb。弹药背包和弹药挂架为其提供的备弹减少一倍。",ra:"0",slot:"10D12",pr:"反坦克",grp:"防御系统",sub:""},{n:"GAM-66 三管加特林机炮",mf:"（5）（7）",part:"机枪（重）",bonus:"200（20mm）",ds:"机炮 射速极高的大口径加特林机炮，通常是武装炮艇的下挂武器。既可以对地压制，又可以对空防御，面对同等级的战车时，也能不落下风。它的所有射击模式消耗弹药x2，长点射时穿甲等级上升一个等级。敌人闪避该武器全自动射击时需要承受-4的减值。",ra:"1",slot:"/",pr:"轻反器材",grp:"防御系统",sub:""},{n:"G-44 速射机枪",mf:"（4）（6）",part:"机枪（重）",bonus:"150（7.62全）",ds:"机枪 HK开发的ACPA火力支援武器，一杆笨重的双管机枪。是当前市面上最好的全威力弹药机枪之一。它的射速非常夸张，因此需要经常更换枪管。它每个射击模式消耗的弹药*2。敌人闪避该武器全自动射击时需要承受-4的减值。",ra:"0",slot:"/",pr:"全威力",grp:"防御系统",sub:""},{n:"军科 MST-40 铅雨",mf:"（6）（8）",part:"机枪（中）",bonus:"300（7mm磁）",ds:"机枪 一种为赛博格和ACPA准备的多管磁轨金属风暴机枪，由于其惊人的重量和夸张的射速，通常不推荐步兵携带。它一共有25根枪管，每次射击都会按顺序从每排枪管发射子弹，并以夸张的火力覆盖能力掩盖其精度不佳的弊病。它的专用弹药价格视为重型冲锋枪弹药，每次短点射发射50发弹药，长点射发射100发弹药，火力压制/扫射发射150发弹药。其穿甲等级等同于轻反器材，且对掩体伤害翻倍。敌人闪避该武器射击时需要承受-10的减值。",ra:"1",slot:"/",pr:"轻反器材",grp:"防御系统",sub:""},{n:"ONI-特攻型 自动霰弹枪",mf:"3（6）",part:"霰弹（中）",bonus:"30（#4）",ds:"霰弹枪 荒坂ACPA小队在巷战使用的特种全自动霰弹枪，改用了4号霰弹以加强它对着甲目标的火力。即便是着甲步兵也很难在其面前生存。范围内的目标即便成功闪避或者未能穿甲，也会受到1d8不可被避免的伤害。荒坂内部有一种专属于它的高穿甲镖弹（穿甲等级提升至轻型反器材），只提供给精锐部队使用。敌人闪避该武器全自动射击时需要承受-4的减值。",ra:"0",slot:"12D6",pr:"中间威力",grp:"防御系统",sub:""},{n:"猎象者 泵动霰弹枪",mf:"2",part:"霰弹（中）",bonus:"8（#2）",ds:"霰弹枪 你能想象到世上最笨重的霰弹枪，常人连拿起它都成问题。它发射专用的2号破甲飞镖霰弹，能对一切目标造成极其恐怖的杀伤。在室内清理软目标时，它的范围更改为16m*6m，且范围内的一切目标都会被穿透（掩体除外）。范围内的目标即便成功闪避或者未能穿甲，也会受到1d8不可被避免的伤害。敌人闪避该武器全自动射击时需要承受-6的减值。",ra:"0",slot:"12D8",pr:"全威力",grp:"防御系统",sub:""},{n:"浪啸军火 25mm速射榴弹枪",mf:"5",part:"重武（中）",bonus:"30（25mm榴）",ds:"突击步枪 荒坂ACPA小队使用的制式突击步枪，但发射的是25mm榴弹。虽然射程比常规的反器材突击步枪要近，但是城区的绞肉能力更强，面对重装甲单位也有一战之力。荒坂部队装备的特制HEAT弹头在市面上很少流通，通常一枚的市场价是原价的两倍以上。",ra:"0",slot:"4D12",pr:"轻反器材",grp:"防御系统",sub:""},{n:"红龙式火焰喷射器",mf:"2",part:"重武（中）",bonus:"20（喷火器燃料）",ds:"火焰喷射器 这把火焰喷射器最远可以喷射50M的距离，并点燃落点3*3范围的所有东西，或者扇形范围9m的所有目标。使用冲锋枪射表。这种喷火器可以轻松造成上千度的高温，命中时无视所有的护甲。每个被喷火器击中的目标和在点燃方格上的目标都会受到每回合1D8的额外伤害。燃烧的方格和人员会持续燃烧三回合才逐渐熄灭。被点燃的目标只能脱下被点燃的衣服才能避免燃烧伤害。对赛博格和机械目标伤害减半。",ra:"0",slot:"4D8",pr:"全威力",grp:"防御系统",sub:""},{n:"马洛里安 侍从冲锋手枪",mf:"3（5）",part:"手枪（轻）",bonus:"40（.50ae）",ds:"手枪 尽管这把为ACPA设计的冲锋手枪只是为了在应急情况下和近身软目标交火使用的，但马洛里安公司还是贴心地将.50ae这样的大口径弹药塞进了它的弹鼓里。它能确保所有妄图贴近ACPA的武装分子在顷刻间化为肉泥，但它的后坐力也大到夸张，不适合由没有穿戴ACPA的单兵操作。敌人闪避该武器全自动射击时需要承受-2的减值。",ra:"1",slot:"5D8",pr:"中间威力",grp:"防御系统",sub:""},{n:"宪法军工 忠诚僚机手枪",mf:"2",part:"手枪（轻）",bonus:"12（.75pp）",ds:"手枪 为ACPA和赛博格特供的超重型手枪，普通人不仅难以承受其重量，也难以承受其夸张的后坐力。特制的19x45mm锥形穿甲弹在近距离保持了优秀的穿甲能力，甚至可以威胁到赛博格和其他ACPA。是装甲骑兵们在室内或者遭遇紧急情况时的首选备用武器。",ra:"0",slot:"6D10",pr:"全威力",grp:"防御系统",sub:""},{n:"罗马工业“尼禄”PM-41-A",mf:"3（6）",part:"冲锋（轻）",bonus:"200（.50nero）",ds:"冲锋枪 这款改型专门为那些使用ACPA的镇爆特警使用，不仅使用弹箱来取代弹匣，还略微增加了射速，以确保能在室内作战释放恐怖的火力压制。它的全自动模式消耗弹药*2，敌人闪避该武器全自动射击时需要承受-4的减值。",ra:"0",slot:"8D6",pr:"中间威力",grp:"防御系统",sub:""},{n:"东和造“苦无”箭弹冲锋枪",mf:"仅全自动 （6）",part:"冲锋（轻）",bonus:"300（7mm箭）",ds:"冲锋枪 服部ACPA通常会装备的轻型冲锋枪，口径虽小但穿甲能力优秀，而且制造的噪音极小，适合潜入作战使用。最大的缺点在于停止力过低，但其恐怖的射速完美弥补了这一点。它的全自动模式消耗弹药*4，该枪的稀有性主要因为荒坂很少出口它专用的7mm箭弹，黑市上的仿制弹药大多只有全威力的穿甲等级。敌人闪避该武器全自动射击时需要承受-8的减值。",ra:"1",slot:"/",pr:"轻反器材",grp:"防御系统",sub:""},{n:"NSM-29 镖弹冲锋枪",mf:"3（5）",part:"冲锋（轻）",bonus:"200（10mm镖）",ds:"冲锋枪 城市镇暴ACPA使用的冲锋枪，停止力优秀，保证穿甲能力的同时不会过度穿透。它的射速很高，可以在巷战交火中有效压制敌方的重火力。其全自动模式消耗两倍弹药。敌人闪避该武器全自动射击时需要承受-4的减值。",ra:"2",slot:"5D6",pr:"中间威力",grp:"防御系统",sub:""},{n:"荒坂 神风 巡航导弹发射器",mf:"1",part:"重武（重）",bonus:"1（1神风-特）",ds:"导弹 使用雷达锁定的巡航导弹放射器，可以无视视线，花费一个动作锁定雷达信号并发射，效果同无人机表的神风-特。弹药背包和弹药挂架为其提供的备弹减少两倍（最少为1）。只能安装智能链接",ra:"0",slot:"见表",pr:"反坦克",grp:"防御系统",sub:""},{n:"60mm迫击炮",mf:"1",part:"重武（中）",bonus:"10（60mm迫）",ds:"迫击炮 无法在100m内使用，但最远距离可达3km。能使用最原始的坐标标记和无人机制导、卫星制导三种方式来进行瞄准。使用时必须搭配液压锚部署在坚硬表面上，无法移动射击。只有装备迫击炮背包才能使用。只能安装智能链接 无人机制导：需要一架使用者可以共享视觉的无人机在可视距离内看见目标，使目标只要在射程范围内，命中目标的DV都取最小值。 卫星制导：需要卫星上行链路，使目标只要在射程范围内，命中的DV都取DV表第二小的数值。",ra:"0",slot:"7D12",pr:"全威力",grp:"防御系统",sub:""},{n:"100mm迫击炮",mf:"1",part:"重武（重）",bonus:"6（100mm迫）",ds:"迫击炮 无法在100m内使用，但最远距离可达10km。能使用最原始的坐标标记和无人机制导、卫星制导三种方式来进行瞄准。使用时必须搭配液压锚部署在坚硬表面上，无法移动射击。只有装备双联迫击炮背包才能使用。只能安装智能链接 无人机制导：需要一架使用者可以共享视觉的无人机在可视距离内看见目标，使目标只要在射程范围内，命中目标的DV都取最小值。 卫星制导：需要卫星上行链路，使目标只要在射程范围内，命中的DV都取DV表第二小的数值。",ra:"0",slot:"10D12",pr:"全威力",grp:"防御系统",sub:""}]};export{r as D};
